"""Saved-evidence analysis. No fitting, model inference, retrieval or revisions."""
from __future__ import annotations
import csv
import hashlib
import html
import io
import json
import math
from collections import Counter, defaultdict
from pathlib import Path
from zipfile import ZipFile
import numpy as np
from step35_statistics_core import (CONTRASTS, CLASSIFIER_CONTRASTS, paired_binary_counts, bootstrap_planner, analyze_classifier_records)
from step35_classifier_inputs import load_classifier, MissingClassifierInput
from step35_retrieval_analysis import analyze_retrieval
from step35_native_runtime_analysis import analyze_runtime_details

DIMENSIONS = ('response_suitability', 'profile_fit', 'practicality_completeness', 'evidence_accuracy', 'clarity')
EXPECTED_CATEGORIES = {'feasible': 150, 'missing_information': 20, 'conflicting_constraints': 15, 'outside_scope': 15}


def sha(data):
    return hashlib.sha256(data).hexdigest()


def packed(value):
    return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + '\n').encode('utf-8')


def rows_from_bytes(data):
    return [json.loads(line) for line in data.splitlines() if line.strip()]


def require(condition, reason):
    if not condition:
        raise ValueError(reason)


def safe_path(root, relative):
    require(isinstance(relative, str) and '\\' not in relative and ':' not in relative, 'Invalid saved evidence path.')
    candidate = (root / relative).resolve()
    require(candidate.is_relative_to(root), 'Saved evidence path leaves the project.')
    return candidate


def csv_content(rows):
    fields = list(dict.fromkeys(key for row in rows for key in row)) if rows else ['status']
    stream = io.StringIO(newline='')
    writer = csv.DictWriter(stream, fieldnames=fields, lineterminator='\n')
    writer.writeheader()
    for row in rows:
        writer.writerow({key: json.dumps(value, ensure_ascii=False, sort_keys=True) if isinstance(value, (list, dict, tuple)) else value
                         for key, value in row.items()})
    return stream.getvalue().encode('utf-8-sig')


def read_planners(root, expected_members):
    archive = root / 'results/step33_saved_results_review.zip'
    with ZipFile(archive) as source:
        members = {name: source.read(name) for name in expected_members}
    require(all(sha(members[name]) == expected for name, expected in expected_members.items()), 'The saved Step 33 comparison export changed.')
    rows = rows_from_bytes(members['saved_outcomes.jsonl']); ledger = rows_from_bytes(members['saved_ledger.jsonl'])
    protocol = json.loads(members['frozen_comparison_protocol.json']); summary = json.loads(members['comparison_summary.json'])
    source_hashes = json.loads(members['source_file_sha256.json'])
    by_job = {row['job_id']: row for row in rows}; entries = {row['job_id']: row for row in ledger}
    require(len(rows) == len(by_job) == len(ledger) == len(entries) == 800 and set(by_job) == set(entries), 'The comparison needs all 800 unique designated outcomes and assessments.')
    for row in rows:
        item = entries[row['job_id']]
        require(item['execution_state'] == 'terminal' and item['assessment_execution'] == 'completed' and item['metric_state'] == 'assessed', 'An unstarted, unresolved or unassessed planner job remains incomplete.')
        for field in ('profile_id', 'family_id', 'planner_version', 'case_category', 'public_record_sha256', 'designated_outcome_sha256', 'assessment_sha256'):
            require(row[field] == item[field], 'A saved planner identity or canonical assessment hash differs: ' + field)
        require(all(item.get(key) == value for key, value in row['final_metrics'].items() if key != 'applicable_category'), 'Ledger and saved metric flags disagree.')
        require(all(type(row['final_metrics'][key]) is bool for key in ('strict_format_valid', 'designated_workflow_completed', 'automated_declared_checks_pass', 'complete_request_fulfillment_verified', 'category_response_success')), 'A missing saved metric cannot be substituted with a failure.')
        primary = row['final_metrics']['automated_feasible_plan_success']
        require((type(primary) is bool) if row['case_category'] == 'feasible' else primary is None, 'The primary metric must remain applicable only to feasible requests.')
        require(row['raw_text_sha256'] == (None if row['raw_text'] is None else sha(row['raw_text'].encode('utf-8'))), 'A saved raw reply differs from its original text hash.')
        require(row['assessment_path'] in source_hashes and source_hashes.get(row['transport_record_path']) == row['transport_record_sha256'], 'The saved assessment/transport source bindings are incomplete.')
    matched = {(row['profile_id'], row['planner_version']): row for row in rows}
    profiles = sorted({row['profile_id'] for row in rows})
    require(len(matched) == 800 and len(profiles) == 200 and all((profile, version) in matched for profile in profiles for version in range(1, 5)), 'The four-planner comparison roster is incomplete.')
    bases = [matched[profile, 1] for profile in profiles]
    require(Counter(row['case_category'] for row in bases) == EXPECTED_CATEGORIES, 'The frozen final scenario denominators differ.')
    for profile in profiles:
        for key in ('family_id', 'case_category', 'public_record_sha256'):
            require(len({matched[profile, version][key] for version in range(1, 5)}) == 1, 'Matched profile metadata differs across planners.')
    require(protocol['metric_definitions']['paired']['contrasts'] == ['V2-V1', 'V3-V2', 'V4-V3', 'V4-V1'], 'The frozen comparison directions differ.')
    candidate_path = safe_path(root, protocol['original_settings_protocol_path'])
    candidate_status = 'bound_in_export_not_reopened'
    input_hashes = {'results/step33_saved_results_review.zip': sha(archive.read_bytes())}
    if candidate_path.is_file():
        raw = candidate_path.read_bytes()
        require(sha(raw) == protocol['original_settings_protocol_sha256'], 'The original planner protocol candidate hash differs.')
        original = json.loads(raw)
        require(original['metric_definitions_candidate'] == protocol['metric_definitions'] and original['order_policy'] == protocol['order_policy'], 'The final protocol differs from its original settings snapshot.')
        input_hashes[protocol['original_settings_protocol_path']] = sha(raw);candidate_status = 'reopened_and_verified'
    return {'rows': rows, 'ledger': ledger, 'matched': matched, 'profiles': profiles, 'bases': bases, 'protocol': protocol,
        'summary': summary, 'source_hashes': source_hashes, 'member_hashes': expected_members, 'input_hashes': input_hashes, 'original_protocol_check': candidate_status}


def read_review(root, planner, expected_review_id):
    pointer = root / 'results/step34_team_review_summary.json'
    summary = json.loads(pointer.read_bytes())
    require(summary['review_id'] == expected_review_id, 'The Step 34 review version differs from this analysis.')
    folder = safe_path(root, summary['review_folder'])
    manifest = json.loads((folder / 'review_manifest.json').read_bytes())
    inputs = {pointer.relative_to(root).as_posix(): sha(pointer.read_bytes())}
    for name, expected in manifest['files'].items():
        path = safe_path(root, (folder / name).relative_to(root).as_posix());raw = path.read_bytes()
        require(sha(raw) == expected, 'A locked team review artifact has changed: ' + name)
        inputs[path.relative_to(root).as_posix()] = expected
    require(all(planner['member_hashes'].get(name) == value for name, value in manifest['source_member_sha256'].items()), 'The review refers to another saved comparison.')
    locked = json.loads((folder / 'rating_lock.json').read_bytes());raw = (folder / 'ratings.jsonl').read_bytes()
    require(locked['ratings_sha256'] == sha(raw), 'The completed review does not match its lock.')
    reviews = rows_from_bytes(raw);bindings = json.loads((folder / 'private_response_binding.json').read_bytes())
    ratings = {review['response_id']: review for review in reviews};key = {row['response_id']: row for row in bindings}
    require(len(reviews) == len(ratings) == len(bindings) == len(key) == 160 and set(ratings) == set(key), 'The selected review needs all 160 unchanged replies.')
    original_key = rows_from_bytes(ZipFile(root / 'results/step33_saved_results_review.zip').read('private_review_binding/private_bound_response_key.jsonl'))
    require(key == {row['response_id']: row for row in original_key}, 'The reviewed sample differs from the pre-output selection.')
    matched_ratings = {}
    for response_id, review in ratings.items():
        binding = key[response_id];outcome = planner['matched'][binding['profile_id'], binding['planner_version']]
        require(binding['response_text_sha256'] == outcome['raw_text_sha256'] and binding['designated_outcome_sha256'] == outcome['designated_outcome_sha256'], 'A review is not bound to its designated reply.')
        require(set(review['ratings']) == set(DIMENSIONS), 'A review dimension is missing.')
        for dimension, rating in review['ratings'].items():
            require((rating['status'] == 'rated' and type(rating['score']) is int and rating['score'] in (0, 1, 2))
                    or (dimension == 'evidence_accuracy' and rating['status'] == 'not_applicable' and rating['score'] is None and bool(rating['rationale'])), 'An unfinished or invalid review entry cannot be imputed.')
            matched_ratings[binding['profile_id'], binding['planner_version'], dimension] = rating
    profiles = sorted({row['profile_id'] for row in bindings})
    require(len(profiles) == 40 and len(matched_ratings) == 800, 'The complete supplementary review needs 40 profiles and 800 dimension entries.')
    require(summary['independent_teammate_ratings_collected'] == 0 and summary['reviewer_agreement']['computed'] is False, 'The review method must remain the executed single assisted review.')
    return {'summary': summary, 'reviews': reviews, 'matched': matched_ratings, 'profiles': profiles, 'input_hashes': inputs}


def metric(row, name):
    if name == 'completed_valid_plan':
        return row['completion_valid'] and row['format_valid'] and row['response_type'] == 'plan'
    if name == 'declared_response_type_match':
        return row['response_type'] == {'missing_information': 'clarification', 'conflicting_constraints': 'constraint_conflict', 'outside_scope': 'outside_scope'}[row['case_category']]
    return row['final_metrics'][name]


def paired_tables(planner):
    rows, population_rows, headline = [], [], []
    metrics = [('all_planner', planner['profiles'], 'strict_format_valid'), ('all_planner', planner['profiles'], 'designated_workflow_completed')]
    for category in EXPECTED_CATEGORIES:
        selected = [row['profile_id'] for row in planner['bases'] if row['case_category'] == category]
        names = ('automated_feasible_plan_success', 'automated_declared_checks_pass', 'complete_request_fulfillment_verified', 'completed_valid_plan') if category == 'feasible' else ('category_response_success', 'declared_response_type_match')
        metrics.extend((category, selected, name) for name in names)
    for population, selected, name in metrics:
        for version in range(1, 5):
            numerator = sum(metric(planner['matched'][profile, version], name) for profile in selected)
            headline.append({'population': population, 'metric': name, 'planner': version, 'numerator': numerator, 'denominator': len(selected), 'percent': 100 * numerator / len(selected),
                'families': len({planner['matched'][profile, version]['family_id'] for profile in selected})})
        for later, earlier in CONTRASTS:
            counts = paired_binary_counts([metric(planner['matched'][profile, later], name) for profile in selected], [metric(planner['matched'][profile, earlier], name) for profile in selected])
            rows.append({'population': population, 'metric': name, 'contrast': f'V{later}-V{earlier}', **counts,
                'later_numerator': sum(metric(planner['matched'][profile, later], name) for profile in selected),
                'earlier_numerator': sum(metric(planner['matched'][profile, earlier], name) for profile in selected),
                'families': len({planner['matched'][profile, 1]['family_id'] for profile in selected})})
    for base in planner['bases']:
        for population in ('all_planner', base['case_category']):
            population_rows.append({'population': population, 'record_id': base['profile_id'], 'group_id': base['family_id'], 'age': base['public_input']['age'], 'case_category': base['case_category']})
    return rows, headline, population_rows


def review_tables(review, planner):
    distributions, paired = [], []
    for version in range(1, 5):
        for dimension in DIMENSIONS:
            ratings = [review['matched'][profile, version, dimension] for profile in review['profiles']]
            counts = Counter(rating['score'] for rating in ratings if rating['status'] == 'rated')
            distributions.append({'review_stream': 'single_assisted_team_review', 'planner': version, 'dimension': dimension,
                'score_0': counts[0], 'score_1': counts[1], 'score_2': counts[2], 'numeric': sum(counts.values()),
                'not_applicable': sum(rating['status'] == 'not_applicable' for rating in ratings), 'missing': 0, 'responses': 40, 'families': 40})
    for later, earlier in CONTRASTS:
        for dimension in DIMENSIONS:
            counts = Counter()
            for profile in review['profiles']:
                a, b = review['matched'][profile, later, dimension], review['matched'][profile, earlier, dimension]
                if a['status'] == b['status'] == 'rated':
                    counts['higher' if a['score'] > b['score'] else 'lower' if a['score'] < b['score'] else 'equal'] += 1
                elif a['status'] == b['status'] == 'not_applicable':
                    counts['both_not_applicable'] += 1
                else:
                    counts['one_not_applicable'] += 1
            paired.append({'review_stream': 'single_assisted_team_review', 'contrast': f'V{later}-V{earlier}', 'dimension': dimension,
                'jointly_numeric_pairs': counts['higher'] + counts['equal'] + counts['lower'], 'higher': counts['higher'], 'equal': counts['equal'], 'lower': counts['lower'],
                'both_not_applicable': counts['both_not_applicable'], 'one_not_applicable': counts['one_not_applicable'], 'missing_pairs': 0, 'profiles': 40,
                'agreement_statistic': None, 'interpretation': 'Descriptive ordinal comparison from one assisted review; not two-rater agreement or a combined quality score.'})
    return distributions, paired


def describe_times(rows):
    values = [float(row['elapsed_seconds']) for row in rows if isinstance(row.get('elapsed_seconds'), (int, float)) and math.isfinite(row['elapsed_seconds']) and row['elapsed_seconds'] >= 0]
    return {'outcomes': len(rows), 'measured': len(values), 'missing': len(rows)-len(values), 'mean_seconds': float(np.mean(values)) if values else None,
        'median_seconds': float(np.median(values)) if values else None, 'p95_seconds': float(np.percentile(values, 95, method='linear')) if values else None,
        'p95_method': 'linear percentile', 'minimum_seconds': min(values) if values else None, 'maximum_seconds': max(values) if values else None}


def runtime_tables(planner):
    times, matched, usage = [], [], []
    for version in range(1, 5):
        group = [row for row in planner['rows'] if row['planner_version'] == version]
        for population, included in (('all_terminal', group), ('workflow_completed', [r for r in group if r['completion_valid']]),
                ('workflow_not_completed', [r for r in group if not r['completion_valid']]), ('strict_format_valid', [r for r in group if r['format_valid']]),
                ('automatic_primary_success', [r for r in group if r['final_metrics']['automated_feasible_plan_success']])):
            times.append({'planner': version, 'population': population, **describe_times(included), 'scope': 'Measured saved end-to-end request time; external scoring excluded.'})
        objects = [row['usage'] for row in group if isinstance(row.get('usage'), dict)]
        for field in ('prompt_eval_count', 'eval_count', 'prompt_eval_cached_count'):
            values = [obj[field] for obj in objects if type(obj.get(field)) is int]
            usage.append({'planner': version, 'measure': field, 'observed_objects': len(values), 'expected_outcomes': 200, 'missing': 200-len(values),
                'value_sum': sum(values) if values else None, 'scope': 'Designated terminal-role usage only; excludes earlier specialist/evaluator/revision calls.', 'unit': 'tokens'})
    for later, earlier in CONTRASTS:
        for population in ('all_terminal', 'both_workflows_completed'):
            differences = []
            for profile in planner['profiles']:
                a, b = planner['matched'][profile, later], planner['matched'][profile, earlier]
                if population == 'both_workflows_completed' and not (a['completion_valid'] and b['completion_valid']):continue
                if all(isinstance(row.get('elapsed_seconds'), (int, float)) and math.isfinite(row['elapsed_seconds']) and row['elapsed_seconds'] >= 0 for row in (a, b)):
                    differences.append(a['elapsed_seconds'] - b['elapsed_seconds'])
            matched.append({'contrast': f'V{later}-V{earlier}', 'population': population, 'matched_profiles': len(differences), 'excluded_profiles': 200-len(differences),
                'mean_paired_difference_seconds': float(np.mean(differences)) if differences else None, 'median_paired_difference_seconds': float(np.median(differences)) if differences else None,
                'uncertainty_interval': None, 'interpretation': 'Observed paired timing difference; no new timing hypothesis test or post-hoc bootstrap introduced.'})
    return times, matched, usage


def diagnostic_tables(planner):
    failure_rows, parent_counts, subgroup_rows = [], defaultdict(Counter), []
    for row in planner['rows']:
        missing = row['raw_text'] is None or not row['raw_text'].strip()
        issue_codes = sorted({issue['code'] for check in (row.get('checks') or []) if isinstance(check, dict) and check.get('check_id') == 'output_structure'
            for issue in (check.get('observed') if isinstance(check.get('observed'), list) else []) if isinstance(issue, dict) and issue.get('code')})
        parents = row['parent_checks']; require(len({p['check_id'] for p in parents}) == len(parents), 'A conceptual parent check is duplicated.')
        violations = [p['check_id'] for p in parents if p['required'] and p['status'] == 'violated']
        unknowns = [p['check_id'] for p in parents if p['required'] and p['status'] == 'unknown']
        for parent in parents:
            require(parent['status'] in ('met', 'violated', 'unknown', 'not_applicable'), 'An assessment status is invalid.')
            for population in ('all_planner', row['case_category']):
                parent_counts[row['planner_version'], population, parent['check_id'], parent['required']][parent['status']] += 1
        failure_rows.append({'job_id': row['job_id'], 'profile_id': row['profile_id'], 'family_id': row['family_id'], 'planner': row['planner_version'], 'case_category': row['case_category'],
            'workflow_completed': row['completion_valid'], 'strict_format_valid': row['format_valid'], 'response_type': row['response_type'], 'missing_reply_text': missing,
            'required_violated': violations, 'required_unknown': unknowns, 'recorded_issue_codes': issue_codes,
            'workflow_error': row.get('workflow_error'), 'failed_stage': row.get('failed_stage'), 'terminal_state': row.get('terminal_state'),
            'internal_review': row.get('internal_review'), 'assessment_path': row['assessment_path'], 'assessment_canonical_sha256': row['assessment_sha256'],
            'designated_outcome_sha256': row['designated_outcome_sha256'], 'note': 'Diagnostic categories overlap. Unknown is not proved unsafe; source byte hashes and canonical assessment hashes use different hash domains.'})
    parent_rows = []
    for (version, population, check_id, required), counts in sorted(parent_counts.items()):
        denominator = 200 if population == 'all_planner' else EXPECTED_CATEGORIES[population]
        applicable = counts['met'] + counts['violated'] + counts['unknown']
        parent_rows.append({'planner': version, 'population': population, 'check_id': check_id, 'required': required, 'case_denominator': denominator,
            'cases_with_parent': sum(counts.values()), 'met': counts['met'], 'violated': counts['violated'], 'unknown': counts['unknown'], 'not_applicable': counts['not_applicable'],
            'coverage': (counts['met'] + counts['violated']) / applicable if applicable else None,
            'coverage_definition': '(met + violated)/(met + violated + unknown); coverage is not a pass rate'})
    for kind, values in (('age', range(13, 18)), ('scenario', EXPECTED_CATEGORIES)):
        for value in values:
            bases = [row for row in planner['bases'] if (row['public_input']['age'] if kind == 'age' else row['case_category']) == value]
            for version in range(1, 5):
                chosen = [planner['matched'][row['profile_id'], version] for row in bases]
                feasible = [row for row in chosen if row['case_category'] == 'feasible']
                subgroup_rows.append({'grouping': kind, 'value': value, 'planner': version, 'profiles': len(chosen), 'families': len({row['family_id'] for row in chosen}),
                    'format_valid': sum(row['format_valid'] for row in chosen), 'workflow_completed': sum(row['completion_valid'] for row in chosen),
                    'feasible_profiles': len(feasible), 'primary_success': sum(row['final_metrics']['automated_feasible_plan_success'] for row in feasible),
                    'interpretation': 'Prespecified age/scenario descriptive summary; not independent-athlete sampling or a new passing threshold.'})
    return failure_rows, parent_rows, subgroup_rows


def build_figures(planner, classifier):
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    plt.rcParams.update({'font.size': 11, 'svg.hashsalt': 'step35-saved-analysis', 'axes.spines.top': False, 'axes.spines.right': False})
    outputs = {}
    fig, axes = plt.subplots(1, 2, figsize=(10, 4))
    labels = ['Planner 1', 'Planner 2', 'Planner 3', 'Planner 4'];colors = ['#326d9c', '#427c84', '#6d6b99', '#a36a45']
    for ax, key, title in ((axes[0], 'strict_format_valid', 'Response format'), (axes[1], 'designated_workflow_completed', 'Workflow completion')):
        counts = [sum(row['final_metrics'][key] for row in planner['rows'] if row['planner_version'] == v) for v in range(1, 5)]
        ax.bar(labels, counts, color=colors);ax.set_ylim(0, 215);ax.set_ylabel('Outcomes out of 200');ax.set_title(title)
        for x, value in enumerate(counts):ax.text(x, value+3, str(value), ha='center')
        ax.tick_params(axis='x', rotation=20)
    fig.suptitle('Saved comparison: 200 matched profiles, four planners');fig.tight_layout()
    stream=io.BytesIO();fig.savefig(stream,format='svg',metadata={'Date':None});plt.close(fig);outputs['figures/planner_execution.svg']=stream.getvalue()
    fig, ax = plt.subplots(figsize=(8, 4.5))
    medians=[]
    for version in range(1, 5):
        values=[row['elapsed_seconds'] for row in planner['rows'] if row['planner_version']==version and isinstance(row.get('elapsed_seconds'),(int,float)) and math.isfinite(row['elapsed_seconds'])]
        medians.append(float(np.median(values)))
    ax.bar(labels,medians,color=colors);ax.set_ylabel('Median end-to-end time (seconds)');ax.set_title('All terminal workflows, including failures (200 per planner)')
    for x,value in enumerate(medians):ax.text(x,value+0.8,f'{value:.2f} s',ha='center')
    ax.set_ylim(0,max(medians)*1.2);fig.tight_layout();stream=io.BytesIO();fig.savefig(stream,format='svg',metadata={'Date':None});plt.close(fig);outputs['figures/planner_runtime.svg']=stream.getvalue()
    if classifier is not None:
        fig,ax=plt.subplots(figsize=(8,4.5)); selected=[row for row in classifier['intervals'] if row['metric']=='macro_f1' and '_minus_' in row['model_or_contrast']]
        names={'logistic_regression_minus_majority':'Logistic − majority','neural_minus_majority':'Neural − majority','neural_minus_logistic_regression':'Neural − logistic'}
        for position,row in enumerate(selected):
            ax.plot([row['lower_95'],row['upper_95']],[position,position],color='#326d9c');ax.plot(row['estimate'],position,'o',color='#326d9c')
        ax.axvline(0,color='#6c737b',linewidth=1);ax.set_yticks(range(len(selected)),[names[row['model_or_contrast']] for row in selected]);ax.set_xlabel('Macro-F1 difference (0–1 scale)');ax.set_title('Paired exercise-group bootstrap: individual 95% intervals');fig.tight_layout()
        stream=io.BytesIO();fig.savefig(stream,format='svg',metadata={'Date':None});plt.close(fig);outputs['figures/classifier_macro_f1_differences.svg']=stream.getvalue()
    return outputs


def findings_text(planner, headline, paired, times, review_paired, classifier, classifier_status, retrieval, native_runtime, method_note):
    lookup = {(row['population'], row['metric'], row['planner']): row for row in headline}
    lines = ['# Step 35 — Results analysis and comparison', '',
        'We analyzed the saved results without retraining models, searching the reference index again, revising replies or changing the original scores. The planner study contains 200 fictional profiles and 800 designated outcomes. All four planners use the same local language model; the comparison concerns the complete workflows.', '',
        '## Planner results', '',
        '| Planner | Valid format | Workflow completed | Valid completed plans | Coded checks passed | Full verification | Median time |',
        '|---|---:|---:|---:|---:|---:|---:|']
    for version in range(1,5):
        h=lambda population,metric: lookup[population,metric,version]
        runtime=next(row for row in times if row['planner']==version and row['population']=='all_terminal')
        lines.append(f"| {version} | {h('all_planner','strict_format_valid')['numerator']}/200 | {h('all_planner','designated_workflow_completed')['numerator']}/200 | {h('feasible','completed_valid_plan')['numerator']}/150 | {h('feasible','automated_declared_checks_pass')['numerator']}/150 | {h('feasible','automated_feasible_plan_success')['numerator']}/150 | {runtime['median_seconds']:.2f} s |")
    lines += ['', 'The baseline has the largest number of valid formats across all 200 profiles and the lowest observed time. Planner 4 has the largest number of completed, valid plan responses among the 150 feasible requests (47), compared with 45, 40 and 39. A valid format is not evidence that a plan meets every request.', '',
        'The primary full-verification result is 0/150 for every planner. The automatic goal check was not implemented, and resource checks cover only a limited set of activity descriptions. These gaps prevented full verification. Saved assessments also contain genuine schedule, session-count and existing-commitment violations. We retain both facts: unknown checks are not passes, and lack of verification is not proof that every plan is unsafe or useless.', '',
        '## Matched comparisons and uncertainty', '',
        'We compare Version 2 minus 1, Version 3 minus 2, Version 4 minus 3, and Version 4 minus 1 on the same profiles. Each binary comparison retains both-success, later-only, earlier-only and neither-success counts. Differences in rates use percentage points.', '',
        'The format-rate differences are −6.5, +2.5, +1.0 and −3.0 percentage points in that order. These are descriptive differences in response format, not proof of better overall planning. Challenge cases remain separate: missing-information handling is 0/20 and conflict handling 0/15 for every planner; outside-scope handling is 3, 5, 8 and 3 out of 15. Planner 4 loses five of Planner 3’s outside-scope successes and adds none.', '',
        'The primary intervals use 2,000 paired family-group resamples, seed 42, with individual 95% percentile endpoints. Every eligible member contributes whenever its group is drawn, including repeated draws. All 150 feasible profiles have different adopted family IDs, so the saved family structure is singleton. We also retain the prespecified wording-pattern sensitivity: the 14-pattern mapping across all 200 profiles has three groups in the feasible subset, containing 52, 50 and 48 profiles. We resample only those eligible groups.', '',
        'All primary success flags are zero, so their saved-output bootstrap intervals and rate differences are [0, 0]. This is a constant distribution produced by these fixed flags and verification limits. It does not establish equivalence, zero real-world uncertainty or an absence of useful differences. No significance test, combined quality score, new pass threshold or winning planner is introduced.', '',
        'The planner protocol specified family pairing, 2,000 resamples, seed 42 and percentile intervals. It did not fix the random-generator family, lexical group order or interpolation convention. We explicitly record PCG64, sorted exact IDs and linear percentiles as a numerical implementation clarification made at analysis time. These choices were already frozen for the classifier. Draws and estimates are saved so the calculations can be reproduced.', '',
        '## Exercise classifier', '']
    if classifier is not None:
        labels={'majority':'Majority baseline','logistic_regression':'L5 logistic regression','neural':'N3 neural classifier'}
        lines += ['The classifier comparison uses the saved predictions for 438 test records in 385 exercise groups and all 16 frozen classes. Macro-F1 remains primary; accuracy, class-level metrics and confusion counts provide context.', '', '| Classifier | Macro-F1 | Accuracy |', '|---|---:|---:|']
        for model,values in classifier['observed'].items():lines.append(f"| {labels[model]} | {values['macro_f1']:.4f} | {100*values['accuracy']:.2f}% |")
        lines += ['', 'We compute all three fixed classifier contrasts using the same 2,000 exercise-group draws. Every resample retains the full class list with zero-division scores of zero, including absent classes in a resample. This measures sensitivity to the existing test groups, not retraining or seed variability. The validation-selected L5 application model remains unchanged.', '', '| Macro-F1 contrast | Observed difference | Individual 95% interval |', '|---|---:|---|']
        for row in classifier['intervals']:
            if row['metric']=='macro_f1' and '_minus_' in row['model_or_contrast']:
                lines.append(f"| {row['model_or_contrast'].replace('_',' ')} | {row['estimate']:+.4f} | [{row['lower_95']:+.4f}, {row['upper_95']:+.4f}] |")
    else:
        lines += ['Classifier uncertainty is unavailable in this execution because the original saved test inputs or predictions could not be read. No development predictions, synthetic scores or new inference are substituted. Reason: ' + classifier_status['reason']]
    lines += ['', '## Retrieval', '']
    if retrieval.get('status','').startswith('verified'):
        r=retrieval['summary'];lines += [f"We retain the original {r['heldout_questions']}-question, {r['question_families']}-family held-out retrieval results. The source labels are 20 supported, two partially supported and eight unsupported. The original ranking denominator is 24 nonempty relevance sets; six empty relevance sets do not receive invented recall. Supported-only ranking uses 20 questions. The broader unsupported-service category contains the two partially supported and eight unsupported questions.", '',
            'The early Step 35 text described a planned 20-answerable/10-unsupported split. We preserve the saved source populations rather than change their labels or denominators. Ranked evidence-set coverage, verified retrieval companion text and actual generation-prompt delivery remain different quantities. Companion preservation does not prove that every required fact reached the planner. No new retrieval intervals or held-out searches are introduced.']
        recorded=r['reported_route_metrics'][0]
        lines += ['', '| Saved retrieval measure | Value | Scored questions |', '|---|---:|---:|',
            f"| Mean Recall@5 | {recorded['mean_recall_at_5']:.4f} | {recorded['ranking_scored_denominator']} |",
            f"| MRR@5 | {recorded['mrr_at_5']:.4f} | {recorded['ranking_scored_denominator']} |",
            f"| Ranked complete-evidence-set coverage@5 | {recorded['complete_evidence_set_coverage_rate_at_5']:.4f} | {recorded['complete_evidence_scored_denominator']} |", '',
            'All 30 saved queries returned candidates, including the ten questions in the broader unsupported-service category. The saved no-match and error counts are zero. Returned references and high ranking scores do not establish that a question is answerable or that abstention works.']
    else:lines += ['Retrieval inputs are unavailable in this execution; no development results replace them. ' + '; '.join(retrieval.get('limitations',[]))]
    lines += ['', '## Supplementary team review', '',
        'The Step 34 review contains 160 replies from 40 selected profiles, with 800 separate dimension entries. It is one ChatGPT-assisted review under Sam’s direction, not two independent teammate rating sets. We retain 799 numeric entries and one justified evidence N/A; agreement and weighted kappa remain unavailable. The assisted findings are descriptive supplementary evidence, not a replacement for the original independent-review design.', '',
        'For each dimension, matched version comparisons report higher, equal and lower ratings. No scores are averaged across dimensions or reviewers. Most paired judgments are ties. For clarity, Planner 4 versus Planner 1 has two higher, 15 equal and 23 lower ratings among 40 profiles. The review sample contains 25 feasible and 15 challenge profiles, overrepresenting challenge cases compared with the full benchmark. Its pooled scores do not estimate all 800 replies.', '',
        '## Runtime, failed work and resource limits', '',
        'All-terminal timing includes failed attempts. Completed-workflow, valid-format and unsuccessful-work timings are also saved separately; paired time differences identify which profiles were included. The observed all-terminal means are approximately 10.44, 18.90, 26.61 and 66.22 seconds. Longer workflows did not deliver a verified primary success in this benchmark. That observation does not establish an isolated causal effect of references, specialist roles or checks.', '',
        f"The frozen comparison summary records {planner['summary']['cumulative_model_submissions']} local model submissions across the full run. This is the cumulative total, not the 67 submissions shown for the final five-case batch. Planner 4’s saved terminal states are 198 revision-limit outcomes and two execution errors; none was internally accepted. Independent scoring remains separate from those internal decisions.", '']
    if native_runtime['status']=='complete':
        lines += ['The original hash-bound runtime journals were also read. We report generation submissions, metadata/render attempts, distinct logical calls, cached role reads and available stage usage separately. Token usage is charged once per saved call ID; repeated reads do not multiply tokens. Missing hardware measurements or dollar-cost calculations remain unavailable.']
    else:
        lines += ['Full native runtime journals are unavailable or incomplete in this execution. Their missing measurements are not treated as zero. The export contains 797 designated-role usage objects; those token counts omit earlier specialist/evaluator/revision work and are not labeled full-workflow costs.']
    lines += ['', '## Interpretation and next step', '',
        'We can compare recorded reliability, format, timing, class predictions and review patterns, but cannot declare a fully verified planner or a general winner. Failures and unknown coverage remain visible, with case identifiers and source hashes. The results concern a constructed benchmark and fixed saved outputs; they do not establish improved athletic performance, clinical suitability or results on real athletes. Future changes based on these findings belong to a new experiment version.', '',
        'Step 36 will check reproduction of the saved analysis and its documented starting route. The original two-independent-teammate review component remains unperformed. All versioned tables, uncertainty draws, figures and limitations are retained with the analysis inputs.', '']
    return '\n'.join(lines)


def simple_report_html(text, files):
    escaped=html.escape(text)
    # We keep the report self-contained except for the generated local figures.
    parts=[]
    for block in escaped.split('\n\n'):
        if block.startswith('# '):parts.append('<h1>'+block[2:]+'</h1>')
        elif block.startswith('## '):parts.append('<h2>'+block[3:]+'</h2>')
        elif block.startswith('|'):
            lines=block.splitlines();cells=[line.strip('|').split('|') for line in lines]
            header='<tr>'+''.join('<th>'+cell.strip()+'</th>' for cell in cells[0])+'</tr>'
            body=''.join('<tr>'+''.join('<td>'+cell.strip()+'</td>' for cell in row)+'</tr>' for row in cells[2:])
            parts.append('<table>'+header+body+'</table>')
        else:parts.append('<p>'+block.replace('\n',' ')+'</p>')
    plots=''.join('<figure><img src="'+name+'" alt="'+html.escape(name)+'"></figure>' for name in files if name.endswith('.svg'))
    return ('<!doctype html><html lang="en"><meta charset="utf-8"><title>Step 35 — Results analysis</title><style>body{font:16px/1.6 system-ui,sans-serif;max-width:1100px;margin:35px auto;padding:0 25px;color:#182837}h1,h2{color:#174569}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;padding:8px;border-bottom:1px solid #cad4df}figure{margin:30px 0}img{max-width:100%;height:auto}p{max-width:1000px}</style>'+''.join(parts)+plots+'</html>').encode('utf-8')


def analyze(root, package):
    root=Path(root).resolve();planner=read_planners(root,package['source_member_sha256'])
    review=read_review(root,planner,package['review_id'])
    comparisons,headline,population_rows=paired_tables(planner)
    review_distributions,review_comparisons=review_tables(review,planner)
    time_rows,paired_time_rows,usage_rows=runtime_tables(planner)
    failures,parents,subgroups=diagnostic_tables(planner)
    patterns=package['wording_pattern_groups'];mapping={profile:group['design_tag'] for group in patterns for profile in group['profile_ids']}
    require(len(mapping)==200 and set(mapping)==set(planner['profiles']), 'The original wording-pattern mapping does not cover the frozen roster.')
    proposed=package['original_family_by_profile'];require(all(planner['matched'][profile,1]['family_id']==family for profile,family in proposed.items()), 'Saved pattern/family evidence differs from adopted families.')
    feasible=[row['profile_id'] for row in planner['bases'] if row['case_category']=='feasible']
    values=[[metric(planner['matched'][profile,version],'automated_feasible_plan_success') for version in range(1,5)] for profile in feasible]
    primary=bootstrap_planner(values,[planner['matched'][profile,1]['family_id'] for profile in feasible],'feasible_adopted_families')
    sensitivity=bootstrap_planner(values,[mapping[profile] for profile in feasible],'feasible_original_wording_patterns_sensitivity')
    input_hashes={**planner['input_hashes'],**review['input_hashes']}
    pattern_path=safe_path(root,package['pattern_source_path'])
    pattern_source_status='exact_historical_mapping_embedded_with_source_hash'
    if pattern_path.is_file():
        raw=pattern_path.read_bytes();require(sha(raw)==package['pattern_source_sha256'],'The original wording-pattern evidence differs.')
        source=json.loads(raw);require(source['shared_design_pattern_groups']==patterns,'The embedded historical pattern mapping differs from its original file.')
        input_hashes[package['pattern_source_path']]=sha(raw);pattern_source_status='native_source_reopened_and_verified'
    classifier=None;classifier_input=None
    try:
        classifier_input=load_classifier(root)
        configuration=classifier_input['analysis_config']
        require(configuration['uncertainty']['resamples']==2000 and configuration['uncertainty']['seed']==42,'The frozen classifier resampling settings differ.')
        require(configuration['contrasts']==['logistic_regression_minus_majority','neural_minus_majority','neural_minus_logistic_regression'],'The frozen classifier contrasts differ.')
        classifier=analyze_classifier_records(classifier_input)
        for model,computed in classifier['observed'].items():
            for name,value in computed.items():require(math.isclose(value,classifier_input['summary']['models'][model][name],rel_tol=0,abs_tol=1e-12),'Recomputed saved classifier metric differs: '+model+'/'+name)
        classifier_status={'status':'complete','records':len(classifier_input['records']),'groups':len(classifier['groups']),'class_count':len(classifier_input['class_order']),'observed':classifier['observed'],'reason':None}
        input_hashes.update(classifier_input['input_sha256'])
        population_rows.extend({'population':'classifier_test','record_id':row['record_id'],'group_id':row['group_id'],'target_label':row['target_label']} for row in classifier_input['records'])
    except MissingClassifierInput as exc:
        classifier_status={'status':'unavailable_saved_inputs','records':None,'groups':None,'reason':str(exc),'new_inference_performed':False}
    retrieval=analyze_retrieval(root);input_hashes.update(retrieval.get('input_sha256',{}))
    native_runtime=analyze_runtime_details(root,planner['rows'],planner['source_hashes'],expected_generation_submissions=planner['summary']['cumulative_model_submissions'])
    require(not native_runtime.get('errors'),'Native runtime evidence failed validation: '+'; '.join(native_runtime.get('errors',[])[:3]))
    input_hashes.update(native_runtime.get('input_sha256',{}))
    method_note={**package['method_note'],'planner_original_protocol_check':planner['original_protocol_check'],'pattern_source_check':pattern_source_status,
        'original_two_independent_reviewer_component_completed':False,'retrieval_population_discrepancy_preserved':retrieval.get('summary',{}).get('protocol_population_discrepancy')}
    intervals=primary['intervals']+sensitivity['intervals']+(classifier['intervals'] if classifier is not None else [])
    estimates=primary['estimates']+sensitivity['estimates']+(classifier['estimates'] if classifier is not None else [])
    population_rows.extend({'population':'supplementary_review','record_id':profile,'group_id':planner['matched'][profile,1]['family_id'],
        'age':planner['matched'][profile,1]['public_input']['age'],'case_category':planner['matched'][profile,1]['case_category']} for profile in review['profiles'])
    population_rows.extend({'population':'wording_pattern_sensitivity','record_id':profile,'group_id':mapping[profile],'case_category':'feasible'} for profile in feasible)
    if retrieval.get('question_rows'):
        population_rows.extend({'population':'retrieval_heldout','record_id':row['query_id'],'group_id':row['question_family_id'],'support_status':row['support_status'],'ranking_eligible':bool(row['relevant_unit_count'])} for row in retrieval['question_rows'])
    settings={'resamples':2000,'seed':42,'generator':'numpy.random.Generator(numpy.random.PCG64(42))','group_order':'sorted exact string IDs',
        'draw_method':'Generator.integers(0, number_of_groups, size=(2000, number_of_groups), dtype=int64)','percentile_endpoints':[2.5,97.5],'percentile_method':'linear',
        'resampled_member_policy':'Every eligible record contributes once per draw of its group; actual resampled record denominator; common draws for matched models.',
        'intervals':'individual 95% intervals; no multiplicity-adjusted simultaneous inference','groups':{'feasible_adopted_families':primary['groups'],'feasible_original_wording_patterns_sensitivity':sensitivity['groups']},
        'numerical_convention_timing':method_note['planner_numerical_clarification'], 'numpy_version':np.__version__}
    if classifier is not None:settings['groups']['classifier_test']=classifier['groups']
    identity={'source_member_sha256':package['source_member_sha256'],'input_sha256':input_hashes,'review_id':package['review_id'],'software_sha256':package['software_sha256'],
        'bootstrap_settings':settings,'method_note':method_note,'classifier_status':classifier_status,'retrieval_status':retrieval['status'],'native_runtime_status':native_runtime['status']}
    analysis_id=sha(packed(identity));relative_folder='results/statistical_analysis/analysis_'+analysis_id[:20];folder=root/relative_folder
    checks=[{'check':'all_designated_planner_jobs_assessed','status':'passed','observed':800,'expected':800},
        {'check':'four_version_pairing','status':'passed','observed':200,'expected':200},
        {'check':'supplementary_review_entries','status':'passed','observed':800,'expected':800},
        {'check':'classifier_saved_input_analysis','status':classifier_status['status'],'observed':classifier_status.get('records'),'expected':438},
        {'check':'retrieval_saved_evidence','status':retrieval['status'],'observed':retrieval.get('summary',{}).get('heldout_questions'),'expected':30},
        {'check':'native_runtime_details','status':native_runtime['status'],'observed':native_runtime.get('observed_jobs'),'expected':800},
        {'check':'primary_bootstrap_draws','status':'passed','observed':len(primary['draws']),'expected':2000},
        {'check':'independent_reviewer_agreement','status':'unavailable_not_collected','observed':0,'expected':2}]
    summary={'schema_version':'step35-statistical-analysis-1','analysis_id':analysis_id,
        'status':'saved_evidence_analysis_complete_with_recorded_limits' if classifier is not None and retrieval['status'].startswith('verified') else 'available_components_analyzed_missing_saved_inputs',
        'planner_profiles':200,'planner_outcomes':800,'feasible_profiles_per_planner':150,'adopted_feasible_families':len(primary['groups']),
        'wording_patterns_full_population':len(patterns),'wording_patterns_in_feasible_subset':len(sensitivity['groups']),
        'review_profiles':40,'review_responses':160,'review_dimension_entries':800,'review_method':'single_assisted_supplementary_review',
        'independent_reviewer_agreement':{'computed':False,'reason':'No two actual independent teammate rating sets were collected.'},
        'paired_planner_contrasts':['V%d-V%d'%pair for pair in CONTRASTS],'resamples':2000,'bootstrap_seed':42,'bootstrap_intervals':len(intervals),
        'classifier':classifier_status,'retrieval':retrieval.get('summary',{'status':retrieval['status']}),'native_runtime_status':native_runtime['status'],
        'cumulative_planner_model_submissions':planner['summary']['cumulative_model_submissions'],'new_model_calls':0,'new_predictions':0,'new_reference_queries':0,
        'original_outcomes_changed':False,'automatic_scores_changed':False,'best_planner_selected':False,'formal_significance_claimed':False,
        'analysis_folder':relative_folder,'report_path':relative_folder+'/analysis_report.html','findings_path':relative_folder+'/statistical_analysis_findings.md',
        'primary_metric_limitation':'Goal check unimplemented; resource coverage limited. Constant zero verification intervals do not prove no useful plans or equal true quality.',
        'pending_original_design_components':['two_independent_teammate_ratings_and_agreement'],
        'headline_planner_rows':headline,'timing_all_terminal':[row for row in time_rows if row['population']=='all_terminal'],
        'input_manifest_sha256':sha(packed(identity))}
    review_subgroups=[]
    for kind,values in (('age',range(13,18)),('scenario',EXPECTED_CATEGORIES)):
        for value in values:
            subset=[profile for profile in review['profiles'] if (planner['matched'][profile,1]['public_input']['age'] if kind=='age' else planner['matched'][profile,1]['case_category'])==value]
            for version in range(1,5):
                for dimension in DIMENSIONS:
                    items=[review['matched'][profile,version,dimension] for profile in subset]
                    counts=Counter(item['score'] for item in items if item['status']=='rated')
                    review_subgroups.append({'grouping':kind,'value':value,'planner':version,'dimension':dimension,'profiles':len(subset),'families':len({planner['matched'][profile,1]['family_id'] for profile in subset}),
                        'score_0':counts[0],'score_1':counts[1],'score_2':counts[2],'not_applicable':sum(item['status']=='not_applicable' for item in items),'missing':0,'review_stream':'single_assisted_supplementary_review'})
    files={'analysis_input_manifest.json':packed(identity),'analysis_method_note.json':packed(method_note),'analysis_populations.csv':csv_content(population_rows),
        'analysis_checks.csv':csv_content(checks),'planner_summary.csv':csv_content(headline),'paired_comparisons.csv':csv_content(comparisons),
        'bootstrap_settings.json':packed(settings),'bootstrap_estimates.csv':csv_content(estimates),'bootstrap_intervals.csv':csv_content(intervals),
        'retrieval_summary.csv':csv_content(retrieval.get('summary_rows',[])),'retrieval_question_analysis.csv':csv_content(retrieval.get('question_rows',[])),
        'retrieval_analysis_status.json':packed({key:value for key,value in retrieval.items() if key not in ('question_rows','summary_rows')}),
        'team_rating_distributions.csv':csv_content(review_distributions),'team_rating_comparisons.csv':csv_content(review_comparisons),
        'subgroup_summary.csv':csv_content(subgroups),'team_review_subgroups.csv':csv_content(review_subgroups),'runtime_resource_summary.csv':csv_content(time_rows),'matched_runtime_comparisons.csv':csv_content(paired_time_rows),
        'designated_role_usage.csv':csv_content(usage_rows),'native_runtime_summary.json':packed(native_runtime),
        'native_runtime_by_planner.csv':csv_content(native_runtime.get('per_planner_rows',[])), 'native_runtime_by_stage.csv':csv_content(native_runtime.get('stage_rows',[])),
        'failure_analysis.csv':csv_content(failures),'parent_check_summary.csv':csv_content(parents),'classifier_analysis_status.json':packed(classifier_status),
        'analysis_summary.json':packed(summary)}
    arrays={'feasible_family_draws':primary['draws'],'feasible_family_denominators':primary['denominators'],
        'wording_pattern_draws':sensitivity['draws'],'wording_pattern_denominators':sensitivity['denominators']}
    if classifier is not None:
        arrays.update(classifier_group_draws=classifier['draws'],classifier_resampled_record_counts=classifier['denominators'])
        files['classifier_per_class_metrics.csv']=csv_content(classifier['class_rows']);files['classifier_confusion_matrices.csv']=csv_content(classifier['confusion_rows'])
        files['classifier_summary.json']=packed(classifier['observed'])
        files['classifier_prediction_analysis.csv']=csv_content([{'record_id':row['record_id'],'group_id':row['group_id'],'model':name,'target_label':row['target_label'],'predicted_label':predicted,'correct':row['target_label']==predicted} for row in classifier_input['records'] for name,predicted in row['predictions'].items()])
    stream=io.BytesIO();np.savez_compressed(stream,**arrays);files['bootstrap_draws.npz']=stream.getvalue()
    files.update(build_figures(planner,classifier))
    text=findings_text(planner,headline,comparisons,time_rows,review_comparisons,classifier,classifier_status,retrieval,native_runtime,method_note)
    files['statistical_analysis_findings.md']=text.encode('utf-8');files['analysis_report.html']=simple_report_html(text,files)
    files['output_manifest.json']=packed({'schema_version':'step35-analysis-output-manifest-1','analysis_id':analysis_id,'files':{name:sha(raw) for name,raw in sorted(files.items())}})
    for name,raw in files.items():
        target=folder/name
        require(not target.exists() or target.read_bytes()==raw,'A previous analysis artifact differs and was preserved: '+name)
    pointer=root/'results/step35_statistical_analysis_summary.json'
    doc=root/'docs/statistical_analysis_findings.md'
    if pointer.exists():
        old=json.loads(pointer.read_bytes());require(old.get('schema_version')==summary['schema_version'],'An unrelated Step 35 summary exists and was preserved.')
        old_folder=safe_path(root,old['analysis_folder'])
        require((old_folder/'analysis_summary.json').read_bytes()==pointer.read_bytes(),'An edited Step 35 index was preserved.')
        if doc.exists():
            require(doc.read_bytes() in ((old_folder/'statistical_analysis_findings.md').read_bytes(),text.encode('utf-8')),'Edited analysis documentation was preserved.')
    if doc.exists() and not pointer.exists():require(doc.read_bytes()==text.encode('utf-8'),'Existing analysis documentation was preserved.')
    # We recheck the evidence bytes before saving derived results.
    for name,expected in input_hashes.items():require(sha(safe_path(root,name).read_bytes())==expected,'An analysis input changed while calculations were running: '+name)
    for name,raw in files.items():
        target=folder/name;target.parent.mkdir(parents=True,exist_ok=True)
        if not target.exists():
            with target.open('xb') as handle:handle.write(raw)
    pointer.parent.mkdir(parents=True,exist_ok=True);doc.parent.mkdir(parents=True,exist_ok=True)
    pointer.write_bytes(packed(summary));doc.write_bytes(text.encode('utf-8'))
    return summary

modules.step35_native_runtime_analysis:
"""Read hash-bound native runtime evidence without importing any model runtime.

HTTP generation starts are submissions/transport attempts, not proof of backend
acceptance. Logical call IDs, repeated role invocations, and cached reads remain
different quantities. Missing native evidence always stays unavailable.
"""
from __future__ import annotations

import hashlib
import json
import math
from collections import Counter, defaultdict
from pathlib import Path, PurePosixPath

PHASES = ("metadata", "render", "generation")
TOKEN_KEYS = ("prompt_eval_count", "eval_count", "prompt_eval_cached_count")


def _sha(data):
    return hashlib.sha256(data).hexdigest()


def _canonical(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False).encode("utf-8")


def _number(value):
    return type(value) in (int, float) and math.isfinite(value) and value >= 0


def _strict_json(raw):
    def unique(items):
        result={}
        for key,value in items:
            if key in result:
                raise ValueError("Duplicate JSON key: " + key)
            result[key]=value
        return result
    def reject_nonfinite(value):
        raise ValueError("Nonfinite JSON number: " + value)
    return json.loads(raw,object_pairs_hook=unique,parse_constant=reject_nonfinite)


class _EvidenceError(ValueError):
    pass


class _MissingEvidence(_EvidenceError):
    pass


def analyze_runtime_details(root, rows, source_file_sha256, *, expected_generation_submissions=2636):
    """Return native counts, usage coverage, and input hashes; never write files.

    ``rows`` are saved_outcomes rows. ``source_file_sha256`` is the frozen
    original-file byte-hash inventory, not canonical JSON object hashes.
    ``expected_generation_submissions`` is the frozen summary's cumulative
    submission count (2636 for the actual 800-job run); tests may supply another.
    """
    root = Path(root).resolve()
    rows = list(rows)
    by_job = {r["job_id"]: r for r in rows}
    versions = sorted({r["planner_version"] for r in rows})
    observed_hashes, missing, errors, cases, calls = {}, [], [], [], []
    jobs_seen, calls_seen = set(), set()
    metrics = {v: Counter() for v in versions}
    references = defaultdict(list)
    role_invocations_global = 0
    saved_role_reads_global = 0
    receipt_cases = 0

    def read(relative, *, journal=False):
        if not isinstance(relative, str):
            raise _EvidenceError("Missing evidence path")
        p = PurePosixPath(relative)
        if p.is_absolute() or any(part in ("..", ".") for part in p.parts) or "\\" in relative or ":" in relative:
            raise _EvidenceError("Unsafe evidence path: " + relative)
        path = (root / relative).resolve()
        if not path.is_relative_to(root):
            raise _EvidenceError("Evidence path leaves root: " + relative)
        expected = source_file_sha256.get(relative)
        if not isinstance(expected, str):
            raise _MissingEvidence("Path is not in frozen source-file hashes: " + relative)
        if not path.is_file():
            raise _MissingEvidence("Native file is absent: " + relative)
        raw = path.read_bytes()
        if _sha(raw) != expected:
            raise _EvidenceError("File-byte SHA256 mismatch: " + relative)
        observed_hashes[relative] = expected
        try:
            if journal:
                if not raw.strip() or not raw.endswith(b"\n"):
                    raise _EvidenceError("Empty or unterminated HTTP journal: " + relative)
                return [_strict_json(line) for line in raw.splitlines()]
            return _strict_json(raw)
        except (ValueError, UnicodeError) as error:
            raise _EvidenceError("Invalid saved JSON: " + relative + ": " + str(error)) from error

    execution_paths = sorted(path for path in source_file_sha256
        if path.endswith("/execution.json") and "/cases/case_" in path)
    if len(by_job) != len(rows):
        errors.append("Duplicate designated saved job IDs")
    if not execution_paths:
        missing.append("No native case execution.json paths are bound in the supplied source-file inventory.")

    for execution_path in execution_paths:
        local_calls, local_jobs, local_references = [], [], []
        try:
            execution = read(execution_path)
            saved_rows = execution.get("outcomes")
            if execution.get("stop_reason") is not None or not isinstance(saved_rows, list) or len(saved_rows) != 4:
                raise _EvidenceError("Case is stopped or does not contain four designated outcomes: " + execution_path)
            if not all(isinstance(s, dict) and s.get("planned_job_id") in by_job for s in saved_rows):
                # Only analyze cases belonging to the requested population.
                if all(isinstance(s, dict) and s.get("planned_job_id") not in by_job for s in saved_rows):
                    continue
                raise _EvidenceError("Case mixes requested and unidentified saved jobs: " + execution_path)
            journal_path = execution.get("transport_trace_path")
            journal = read(journal_path, journal=True)
            starts, ends = {}, {}
            for event in journal:
                if not isinstance(event, dict):
                    raise _EvidenceError("Journal contains a non-object event: " + journal_path)
                target = starts if event.get("event")=="http_started" else ends if event.get("event") in ("http_finished", "http_exception") else None
                if target is not None:
                    http_id = event.get("http_id")
                    if not isinstance(http_id, str) or not http_id or http_id in target:
                        raise _EvidenceError("Missing/duplicate HTTP identifier: " + journal_path)
                    target[http_id] = event
            if not starts or set(starts) != set(ends):
                raise _EvidenceError("HTTP starts and terminal events are not one-to-one: " + journal_path)
            manifests = {event.get("manifest_id") for event in journal}
            if len(manifests)!=1 or None in manifests:
                raise _EvidenceError("Journal has missing/mixed native manifest IDs: " + journal_path)
            native_manifest = next(iter(manifests))
            native_jobs = {}
            for saved in saved_rows:
                planned = saved["planned_job_id"]
                row = by_job[planned]
                if planned in jobs_seen or planned in local_jobs:
                    raise _EvidenceError("Duplicate designated job across native cases: " + planned)
                if saved.get("planner_version") != row["planner_version"]:
                    raise _EvidenceError("Planner identity mismatch: " + planned)
                outcome = saved.get("outcome")
                if not isinstance(outcome, dict) or _sha(_canonical(outcome)) != row["designated_outcome_sha256"]:
                    raise _EvidenceError("Native execution designated outcome mismatch: " + planned)
                path = saved.get("transport_record_path")
                if path != row.get("transport_record_path") or saved.get("transport_record_sha256") != row.get("transport_record_sha256"):
                    raise _EvidenceError("Native job-record binding differs from saved outcome: " + planned)
                record = read(path)
                if observed_hashes[path] != row["transport_record_sha256"]:
                    raise _EvidenceError("Native job-record byte hash differs from designated saved binding: " + planned)
                body = {k:v for k,v in record.items() if k!="job_record_sha256"}
                if record.get("job_record_sha256") != _sha(_canonical(body)):
                    raise _EvidenceError("Native job-record canonical seal mismatch: " + planned)
                native_id = record.get("job_id")
                if (not isinstance(native_id, str) or native_id in native_jobs
                        or record.get("manifest_id") != native_manifest
                        or record.get("planner_version") != row["planner_version"]):
                    raise _EvidenceError("Native job identity mismatch: " + planned)
                native_outcome_path = str(PurePosixPath(path).parent / "outcome.json")
                native_outcome = read(native_outcome_path)
                if (record.get("outcome_sha256") != observed_hashes[native_outcome_path]
                        or _canonical(native_outcome) != _canonical(outcome)):
                    raise _EvidenceError("Native outcome file differs from execution: " + planned)
                native_jobs[native_id] = (planned, row["planner_version"])
                local_jobs.append(planned)
                local_references.append((row["planner_version"], planned, record.get("reference_record")))
            per_call = {}
            phase_counts = Counter()
            for http_id, event in starts.items():
                terminal = ends[http_id]
                identity = ("manifest_id", "job_id", "planner_version", "call_id", "stage", "phase", "endpoint")
                if any(event.get(k)!=terminal.get(k) for k in identity):
                    raise _EvidenceError("HTTP terminal identity differs from its start: " + http_id)
                if terminal.get("unresolved") is True:
                    raise _EvidenceError("Unresolved native HTTP observation: " + http_id)
                phase = event.get("phase")
                if phase not in PHASES or event.get("job_id") not in native_jobs:
                    raise _EvidenceError("Unknown phase/native job in journal: " + http_id)
                planned, version = native_jobs[event["job_id"]]
                if event.get("planner_version") != version:
                    raise _EvidenceError("HTTP planner and native job disagree: " + http_id)
                call_id, stage = event.get("call_id"), event.get("stage")
                if not isinstance(call_id,str) or not call_id or not isinstance(stage,str) or not stage:
                    raise _EvidenceError("HTTP call/stage identity is missing: " + http_id)
                if call_id in calls_seen:
                    raise _EvidenceError("Logical call ID reused across native cases: " + call_id)
                call = per_call.setdefault(call_id, {"call_id":call_id,"planned_job_id":planned,"native_job_id":event["job_id"],
                    "planner_version":version,"stage":stage,"phase_counts":Counter(),"http_errors":0})
                if (call["planned_job_id"],call["planner_version"],call["stage"]) != (planned,version,stage):
                    raise _EvidenceError("Logical call maps to different jobs/stages: " + call_id)
                call["phase_counts"][phase] += 1
                call["http_errors"] += terminal["event"]=="http_exception"
                phase_counts[phase] += 1
            if any(c["phase_counts"][phase]>1 for c in per_call.values() for phase in ("render","generation")):
                raise _EvidenceError("A logical role repeats a render/generation transport despite the frozen no-resubmission trace policy: " + journal_path)
            summary_path = execution.get("transport_summary_path")
            if summary_path is None:
                summary_path = str(PurePosixPath(journal_path).parent / "transport_engine_summary.json")
            receipt = None
            try:
                receipt = read(summary_path)
            except _MissingEvidence:
                if execution.get("recovered_without_submission") is not True:
                    raise
            role_usage = {}
            receipt_role_invocations = receipt_saved_reads = None
            if receipt is not None:
                totals = receipt.get("cumulative_trace") or {}
                if (receipt.get("manifest_id") != native_manifest or totals.get("manifest_id") != native_manifest
                        or totals.get("http_requests") != len(starts) or totals.get("http_without_terminal_event") != []
                        or totals.get("uncertain") is not False
                        or any(totals.get(phase+"_transport_attempts") != phase_counts[phase] for phase in PHASES)):
                    raise _EvidenceError("Transport summary disagrees with native journal: " + summary_path)
                generated = sorted(cid for cid,c in per_call.items() if c["phase_counts"]["generation"])
                if totals.get("generation_call_ids") != generated:
                    raise _EvidenceError("Summary generation call IDs differ from journal: " + summary_path)
                role_usage = totals.get("role_usage") or {}
                if not isinstance(role_usage,dict) or not set(role_usage).issubset(per_call):
                    raise _EvidenceError("Role usage contains an unmapped call ID: " + summary_path)
                if any(not isinstance(item,dict) or item.get("charged_once_by_call_id") is not True for item in role_usage.values()):
                    raise _EvidenceError("Role usage does not preserve once-per-call accounting: " + summary_path)
                if totals.get("unique_recorded_roles") != len(role_usage):
                    raise _EvidenceError("Summary logical-role usage count differs: " + summary_path)
                receipt_role_invocations = totals.get("role_invocations")
                receipt_saved_reads = totals.get("saved_role_reads")
                if type(receipt_role_invocations) is not int or type(receipt_saved_reads) is not int or min(receipt_role_invocations,receipt_saved_reads)<0:
                    raise _EvidenceError("Invalid role-invocation/cache-read totals: " + summary_path)
            for cid, call in sorted(per_call.items()):
                usage_item = role_usage.get(cid)
                usage = usage_item.get("usage") if isinstance(usage_item,dict) else None
                native = usage if isinstance(usage,dict) else {}
                local_calls.append({k:v for k,v in call.items() if k!="phase_counts"} | {
                    **{phase+"_transport_attempts":call["phase_counts"][phase] for phase in PHASES},
                    "role_usage_recorded":isinstance(usage_item,dict),
                    **{k:native.get(k) if type(native.get(k)) is int and native[k]>=0 else None for k in TOKEN_KEYS},
                    "native_total_duration_ns":native.get("total_duration") if _number(native.get("total_duration")) else None,
                    "observed_first_role_wall_seconds":usage_item.get("observed_first_role_wall_seconds") if isinstance(usage_item,dict) and _number(usage_item.get("observed_first_role_wall_seconds")) else None,
                    "first_observation_cached":usage_item.get("first_observation_cached") if isinstance(usage_item,dict) else None,
                    "status":usage_item.get("status") if isinstance(usage_item,dict) else None})
            # Commit a case only after all its bindings and reconciliations pass.
            jobs_seen.update(local_jobs)
            calls_seen.update(c["call_id"] for c in local_calls)
            calls.extend(local_calls)
            for version,planned,reference in local_references:
                references[version].append((planned,reference))
            for saved in saved_rows:
                metrics[by_job[saved["planned_job_id"]]["planner_version"]]["observed_jobs"] += 1
            if receipt is not None:
                receipt_cases += 1
                role_invocations_global += receipt_role_invocations
                saved_role_reads_global += receipt_saved_reads
            cases.append({"execution_path":execution_path,"native_manifest_id":native_manifest,"jobs":len(local_jobs),
                "http_requests":len(starts),**{p+"_transport_attempts":phase_counts[p] for p in PHASES},
                "summary_present":receipt is not None,"role_invocations":receipt_role_invocations,"saved_role_reads":receipt_saved_reads})
        except _MissingEvidence as error:
            missing.append(str(error))
        except (KeyError, TypeError, _EvidenceError) as error:
            errors.append(str(error))

    full = len(jobs_seen)==len(rows) and bool(rows) and not errors
    submissions = sum(c["generation_transport_attempts"] for c in calls)
    if full and expected_generation_submissions is not None and submissions != expected_generation_submissions:
        errors.append("Generation submissions disagree with frozen cumulative total: observed " + str(submissions) + ", expected " + str(expected_generation_submissions))
        full = False
    status = "invalid" if errors else "complete" if full else "partial" if jobs_seen else "unavailable"

    def aggregate(selected, scope_complete):
        answer = {"logical_roles_observed":len(selected),
            "logical_roles_with_generation_submission":sum(c["generation_transport_attempts"]>0 for c in selected),
            "observed_generation_submissions":sum(c["generation_transport_attempts"] for c in selected),
            "generation_submissions":sum(c["generation_transport_attempts"] for c in selected) if scope_complete else None,
            "observed_transport_attempts":sum(c[p+"_transport_attempts"] for c in selected for p in PHASES),
            "transport_attempts":sum(c[p+"_transport_attempts"] for c in selected for p in PHASES) if scope_complete else None,
            "http_exception_events":sum(c["http_errors"] for c in selected),
            "usage_objects":sum(c["role_usage_recorded"] for c in selected)}
        for phase in PHASES:
            answer[phase+"_transport_attempts"] = sum(c[phase+"_transport_attempts"] for c in selected) if scope_complete else None
        for key in (*TOKEN_KEYS,"native_total_duration_ns","observed_first_role_wall_seconds"):
            values=[c[key] for c in selected if c[key] is not None]
            answer[key+"_measured_calls"]=len(values)
            answer[key+"_missing_calls"]=len(selected)-len(values)
            answer[key+"_observed_sum"]=sum(values) if values else None
            answer[key+"_sum"]=sum(values) if selected and len(values)==len(selected) and scope_complete else None
        answer["token_usage_status"] = "complete" if selected and scope_complete and all(answer[k+"_missing_calls"]==0 for k in TOKEN_KEYS) else "partial" if answer["usage_objects"] else "unavailable"
        return answer

    per_planner=[]
    for version in versions:
        selected=[c for c in calls if c["planner_version"]==version]
        expected_jobs=sum(r["planner_version"]==version for r in rows)
        complete = metrics[version]["observed_jobs"]==expected_jobs and not errors
        ref_items=references[version]
        ref_records=[item for _job,item in ref_items if isinstance(item,dict)]
        prep=[r.get("preparation_seconds") for r in ref_records if _number(r.get("preparation_seconds"))]
        ref_count_keys=sorted({k for item in ref_records if isinstance(item.get("counts"),dict) for k in item["counts"]})
        references_complete=complete and len(ref_records)==expected_jobs
        ref_counts={k:sum(item["counts"][k] for item in ref_records) if all(type(item.get("counts",{}).get(k)) is int and item["counts"][k]>=0 for item in ref_records) and references_complete else None for k in ref_count_keys}
        per_planner.append({"planner_version":version,"expected_jobs":expected_jobs,"observed_jobs":metrics[version]["observed_jobs"],
            "status":"complete" if complete else status,
            **aggregate(selected,complete),"reference_records":len(ref_records),
            "reference_status":"not_applicable" if version==1 else "complete" if references_complete else "partial" if ref_records else "unavailable",
            "reference_preparation_measured_jobs":len(prep),
            "reference_preparation_seconds_observed_sum":sum(prep) if prep else None,
            "reference_preparation_seconds_sum":sum(prep) if complete and len(prep)==expected_jobs else None,
            "reference_counts":ref_counts,"reference_counts_json":json.dumps(ref_counts,sort_keys=True),
            "role_invocations":None,"saved_role_reads":None,
            "role_invocations_missing_reason":"Bound cumulative receipts provide case totals; journal call IDs identify distinct roles, not repeated cached role invocations by planner.",
            "hardware_measurements":None,"dollar_cost":None})
    stages=[]
    for version,stage in sorted({(c["planner_version"],c["stage"]) for c in calls}):
        selected=[c for c in calls if c["planner_version"]==version and c["stage"]==stage]
        stages.append({"planner_version":version,"stage":stage,**aggregate(selected,full)})
    return {"schema_version":"step35-native-runtime-readonly-1","status":status,
        "missing_reason":"; ".join(missing[:5]) if missing else None,"missing_evidence":missing,"errors":errors,
        "expected_jobs":len(rows),"observed_jobs":len(jobs_seen),"observed_cases":len(cases),
        "expected_generation_submissions":expected_generation_submissions,
        "generation_submissions":submissions if full else None,"observed_generation_submissions":submissions,
        "frozen_global_total_reconciled":full and submissions==expected_generation_submissions if expected_generation_submissions is not None else None,
        "per_planner_rows":per_planner,"stage_rows":stages,"call_rows":calls,"case_rows":cases,
        "input_sha256":observed_hashes,
        "role_invocations":role_invocations_global if full and receipt_cases==len(cases) else None,
        "saved_role_reads":saved_role_reads_global if full and receipt_cases==len(cases) else None,
        "unavailable_metrics":{"hardware_resource_measurements":None,"documented_dollar_cost":None},
        "counting_notes":["Generation http_started events count leaf transport submissions, not inferred backend acceptance.",
            "All HTTP phases contribute transport attempts; metadata and render attempts are separate from generation.",
            "Logical call IDs are deduplicated once for usage, preserving repeated/cached invocation totals separately.",
            "Receipt role usage is first-observation usage charged once by call_id; cached re-reads do not multiply tokens.",
            "Reference preparation is reported from original per-job records; new_counts from a resumed execution do not replace original counts.",
            "Observed sums from a partial population are explicitly labeled; missing counts and token usage are not zero."]}

modules.step35_statistics_core:
"""Paired group resampling for the saved benchmark outputs."""
from __future__ import annotations
import numpy as np

CONTRASTS = ((2, 1), (3, 2), (4, 3), (4, 1))
CLASSIFIER_CONTRASTS = (('logistic_regression', 'majority'), ('neural', 'majority'), ('neural', 'logistic_regression'))


def prepare_group_draws(group_ids, resamples=2000, seed=42):
    groups = sorted(set(group_ids))
    if not groups or any(not isinstance(group, str) or not group for group in groups):
        raise ValueError('Resampling requires nonempty exact string group IDs.')
    index = {group: number for number, group in enumerate(groups)}
    member_groups = np.asarray([index[group] for group in group_ids], dtype=np.int64)
    generator = np.random.Generator(np.random.PCG64(seed))
    draws = generator.integers(0, len(groups), size=(resamples, len(groups)), dtype=np.int64)
    return groups, member_groups, draws


def group_member_weights(member_groups, drawn_groups, group_count):
    return np.bincount(drawn_groups, minlength=group_count)[member_groups]


def percentile_interval(estimates):
    values = np.asarray(estimates, dtype=float)
    if values.ndim != 1 or not len(values) or not np.all(np.isfinite(values)):
        raise ValueError('Bootstrap estimates must all be finite; no discarded resamples.')
    low, high = np.percentile(values, [2.5, 97.5], method='linear')
    return float(low), float(high)


def paired_binary_counts(later, earlier):
    a, b = np.asarray(later), np.asarray(earlier)
    if a.shape != b.shape or a.ndim != 1 or not len(a):
        raise ValueError('Matched binary outcomes must have the same nonempty roster.')
    if any(type(value) not in (bool, np.bool_) for value in list(a) + list(b)):
        raise ValueError('Binary outcomes must be observed booleans, not missing work.')
    return {'both_succeed': int(np.sum(a & b)), 'later_only': int(np.sum(a & ~b)),
            'earlier_only': int(np.sum(~a & b)), 'neither_succeeds': int(np.sum(~a & ~b)),
            'profiles': len(a), 'difference_percentage_points': float(100 * (np.sum(a) - np.sum(b)) / len(a))}


def bootstrap_planner(values, group_ids, population):
    matrix = np.asarray(values, dtype=float)
    if matrix.ndim != 2 or matrix.shape != (len(group_ids), 4) or not np.all(np.isin(matrix, [0, 1])):
        raise ValueError('Planner bootstrap requires four complete binary outcomes per profile.')
    groups, member_groups, draws = prepare_group_draws(group_ids)
    estimates = np.zeros((len(draws), 8), dtype=float)
    denominators = np.zeros(len(draws), dtype=np.int64)
    for replicate, drawn_groups in enumerate(draws):
        weights = group_member_weights(member_groups, drawn_groups, len(groups))
        denominators[replicate] = int(np.sum(weights))
        if denominators[replicate] <= 0:
            raise ValueError('An empty planner resample cannot be silently omitted.')
        estimates[replicate, :4] = 100 * (weights @ matrix) / denominators[replicate]
        for column, (later, earlier) in enumerate(CONTRASTS, start=4):
            estimates[replicate, column] = estimates[replicate, later - 1] - estimates[replicate, earlier - 1]
    observed = np.concatenate((100 * np.mean(matrix, axis=0),
        np.asarray([100 * np.mean(matrix[:, a-1] - matrix[:, b-1]) for a, b in CONTRASTS])))
    names = ['V' + str(version) for version in range(1, 5)] + ['V%d-V%d' % pair for pair in CONTRASTS]
    interval_rows, estimate_rows = [], []
    for column, name in enumerate(names):
        low, high = percentile_interval(estimates[:, column])
        constant = bool(np.all(estimates[:, column] == estimates[0, column]))
        unit = 'percent' if column < 4 else 'percentage_points'
        interval_rows.append({'population': population, 'metric': 'automated_feasible_plan_success',
            'model_or_contrast': name, 'estimate': float(observed[column]), 'lower_95': low, 'upper_95': high,
            'unit': unit, 'profiles': len(matrix), 'groups': len(groups), 'resamples': len(draws),
            'status': 'constant_on_saved_outputs' if constant else 'computed',
            'interpretation': ('Benchmark resampling only. All saved success flags are zero; this does not establish equivalence or zero real-world uncertainty.' if constant and np.all(matrix == 0) else 'Benchmark resampling of fixed saved outcomes only; a constant distribution does not establish zero real-world uncertainty.')})
        estimate_rows.extend({'population': population, 'metric': 'automated_feasible_plan_success', 'model_or_contrast': name,
            'replicate': i + 1, 'estimate': float(value), 'unit': unit, 'resampled_records': int(denominators[i])}
            for i, value in enumerate(estimates[:, column]))
    return {'groups': groups, 'member_groups': member_groups, 'draws': draws, 'denominators': denominators,
            'estimates': estimate_rows, 'intervals': interval_rows}


def classifier_measures(actual, predicted, class_count, weights=None):
    y, p = np.asarray(actual, dtype=np.int64), np.asarray(predicted, dtype=np.int64)
    if y.shape != p.shape or y.ndim != 1 or not len(y):
        raise ValueError('Classifier targets and saved predictions must align exactly.')
    if np.any(y < 0) or np.any(y >= class_count) or np.any(p < 0) or np.any(p >= class_count):
        raise ValueError('A saved class index is outside the frozen class list.')
    w = np.ones(len(y), dtype=float) if weights is None else np.asarray(weights, dtype=float)
    if w.shape != y.shape or np.any(w < 0) or not np.all(np.isfinite(w)) or np.sum(w) <= 0:
        raise ValueError('Classifier resampling weights must have a positive finite denominator.')
    confusion = np.bincount(y * class_count + p, weights=w, minlength=class_count * class_count).reshape(class_count, class_count)
    tp = np.diag(confusion); support = confusion.sum(axis=1); called = confusion.sum(axis=0)
    precision = np.divide(tp, called, out=np.zeros_like(tp), where=called != 0)
    recall = np.divide(tp, support, out=np.zeros_like(tp), where=support != 0)
    f1 = np.divide(2 * tp, support + called, out=np.zeros_like(tp), where=(support + called) != 0)
    return {'macro_f1': float(np.mean(f1)), 'accuracy': float(np.sum(tp) / np.sum(w)),
            'confusion': confusion, 'precision': precision, 'recall': recall, 'f1': f1, 'support': support}


def analyze_classifier_records(data):
    records, labels = data['records'], data['class_order']
    positions = {label: index for index, label in enumerate(labels)}
    actual = np.asarray([positions[row['target_label']] for row in records], dtype=np.int64)
    if set(actual) != set(range(len(labels))):
        raise ValueError('An original test class is unexpectedly absent.')
    predictions = {model: np.asarray([positions[row['predictions'][model]] for row in records], dtype=np.int64)
                   for model in ('majority', 'logistic_regression', 'neural')}
    groups, member_groups, draws = prepare_group_draws([row['group_id'] for row in records])
    observed = {model: classifier_measures(actual, prediction, len(labels)) for model, prediction in predictions.items()}
    columns = [(model, metric) for model in predictions for metric in ('macro_f1', 'accuracy')]
    columns += [(later + '_minus_' + earlier, metric) for later, earlier in CLASSIFIER_CONTRASTS for metric in ('macro_f1', 'accuracy')]
    estimates = np.zeros((len(draws), len(columns)))
    denominators = np.zeros(len(draws), dtype=np.int64)
    for replicate, drawn_groups in enumerate(draws):
        weights = group_member_weights(member_groups, drawn_groups, len(groups))
        denominators[replicate] = int(np.sum(weights))
        computed = {model: classifier_measures(actual, prediction, len(labels), weights) for model, prediction in predictions.items()}
        for column, (name, metric) in enumerate(columns):
            if '_minus_' in name:
                later, earlier = name.split('_minus_', 1)
                value = computed[later][metric] - computed[earlier][metric]
            else:
                value = computed[name][metric]
            estimates[replicate, column] = value
    intervals, estimate_rows, class_rows, confusion_rows = [], [], [], []
    for column, (name, metric) in enumerate(columns):
        if '_minus_' in name:
            later, earlier = name.split('_minus_', 1); point = observed[later][metric] - observed[earlier][metric]
        else:
            point = observed[name][metric]
        low, high = percentile_interval(estimates[:, column])
        intervals.append({'population': 'classifier_test', 'metric': metric, 'model_or_contrast': name,
            'estimate': float(point), 'lower_95': low, 'upper_95': high, 'unit': 'raw_0_to_1_score_difference' if '_minus_' in name else 'proportion',
            'profiles': len(records), 'groups': len(groups), 'resamples': len(draws), 'status': 'computed',
            'interpretation': 'Saved test-record sensitivity with exercise-group resampling; does not measure retraining or seed variability.'})
        estimate_rows.extend({'population': 'classifier_test', 'metric': metric, 'model_or_contrast': name, 'replicate': i + 1,
            'estimate': float(value), 'unit': 'raw_0_to_1_score_difference' if '_minus_' in name else 'proportion', 'resampled_records': int(denominators[i])}
            for i, value in enumerate(estimates[:, column]))
    for model, metrics in observed.items():
        for class_index, label in enumerate(labels):
            class_rows.append({'model': model, 'class_label': label, 'precision': float(metrics['precision'][class_index]),
                'recall': float(metrics['recall'][class_index]), 'f1': float(metrics['f1'][class_index]), 'record_support': int(metrics['support'][class_index]),
                'distinct_group_support': len({records[i]['group_id'] for i in np.flatnonzero(actual == class_index)})})
            for predicted_index, predicted_label in enumerate(labels):
                confusion_rows.append({'model': model, 'actual_class': label, 'predicted_class': predicted_label,
                    'records': int(metrics['confusion'][class_index, predicted_index]),
                    'row_normalized': float(metrics['confusion'][class_index, predicted_index] / metrics['support'][class_index])})
    return {'observed': {name: {'macro_f1': value['macro_f1'], 'accuracy': value['accuracy']} for name, value in observed.items()},
            'intervals': intervals, 'estimates': estimate_rows, 'groups': groups, 'member_groups': member_groups,
            'draws': draws, 'denominators': denominators, 'class_rows': class_rows, 'confusion_rows': confusion_rows}

step36_sources.comparison_driver:
"""Compare saved and reproduced analysis in the installed analysis environment."""
from pathlib import Path
import argparse
import json
import sys
from reproduction_compare import compare_outputs, comparison_policy


def main():
    parser=argparse.ArgumentParser();parser.add_argument('--config',required=True);args=parser.parse_args()
    config=json.loads(Path(args.config).read_text(encoding='utf-8'))
    output=Path(config['comparison_json']);output.parent.mkdir(parents=True,exist_ok=True)
    try:
        if config['declared_policy'] != comparison_policy():
            raise ValueError('Comparison rules differ from the policy declared before execution.')
        if any(config[key]!=config['declared_policy'][key] for key in ('rtol','atol')):
            raise ValueError('Numerical tolerances differ from the policy declared before execution.')
        rows=compare_outputs(config['original_folder'],config['reproduced_folder'],{'rtol':config['rtol'],'atol':config['atol']})
        result={'schema_version':'step36-result-comparison-1','status':'passed' if rows and all(row['status']=='passed' for row in rows) else 'failed',
            'comparison_rows':rows,'files_compared':len(rows),'python':sys.executable}
    except Exception as exc:
        result={'schema_version':'step36-result-comparison-1','status':'failed','comparison_rows':[],
                'files_compared':0,'error_type':type(exc).__name__,'error':str(exc),'python':sys.executable}
    output.write_text(json.dumps(result,sort_keys=True,indent=2,allow_nan=False)+'\n',encoding='utf-8')
    return 0 if result['status']=='passed' else 1


if __name__=='__main__':
    raise SystemExit(main())

step36_sources.reproduction_compare:
"""Read-only, field-specific comparison of versioned Step 35 analysis outputs.

``compare_outputs`` never writes, imputes, sorts rows, drops fields, or silently
normalizes data.  Rules are declared here before looking at comparison results.
Discrete cells (including numeric IDs, counts and denominators) are exact text;
only listed measurement cells receive rtol=1e-10, atol=1e-12 by default.  Empty
cells remain empty and NaN/Inf are rejected in measurement cells.

Permitted differences are narrowly scoped:
* decoded NPZ members, dtype, shape and values are exact; ZIP metadata is not data;
* two named NumPy version fields may differ (both values are recorded);
* analysis IDs and report locations are independently bound to each run's input
  manifest SHA256; manifest file hashes are checked against that run's files;
* configured root relocations apply only at explicitly named JSON pointers;
* known SVG figures use font-verified labels and source chart geometry when
  presentation differs. If glyph decoding is unavailable, only complete vector
  identity apart from metadata plus passing source comparisons can establish
  reproduction equality; that route is reported without a semantic-decoding claim.

``config`` accepts ``rtol``, ``atol``, ``json_environment_fields`` (mapping of
filename to exact JSON pointers), ``json_path_fields`` (same shape), and
``original_root``/``reproduced_root`` for the named relocatable path fields.
Environment allowances add to the two defaults and apply only to strings; use
them only for actual recorded software/environment version fields, never data.
Every permitted difference is listed in the per-file details.  Unknown config
keys are rejected.  Defaults and ``comparison_policy()`` are JSON serializable.

Team review provenance is preserved verbatim.  A single assisted team review
does not become two independent raters or an agreement calculation.
"""
from __future__ import annotations

import csv
import hashlib
import json
import math
import re
from pathlib import Path, PurePosixPath
from fractions import Fraction
from functools import lru_cache
from typing import Any, Mapping
import xml.etree.ElementTree as ET

import numpy as np


# Enumerated measurement columns; all other CSV columns compare exactly.
CSV_MEASUREMENTS = {
    "bootstrap_estimates.csv": ("estimate",),
    "bootstrap_intervals.csv": ("estimate", "lower_95", "upper_95"),
    "planner_summary.csv": ("percent",),
    "paired_comparisons.csv": ("difference_percentage_points",),
    "parent_check_summary.csv": ("coverage",),
    "classifier_per_class_metrics.csv": ("precision", "recall", "f1"),
    "classifier_confusion_matrices.csv": ("row_normalized",),
    "retrieval_summary.csv": ("value",),
    "retrieval_question_analysis.csv": ("recall_at_5", "reciprocal_rank_at_5"),
    "runtime_resource_summary.csv": (
        "mean_seconds", "median_seconds", "p95_seconds", "minimum_seconds", "maximum_seconds"
    ),
    "matched_runtime_comparisons.csv": (
        "mean_paired_difference_seconds", "median_paired_difference_seconds"
    ),
    "native_runtime_by_planner.csv": (
        "observed_first_role_wall_seconds_observed_sum", "observed_first_role_wall_seconds_sum",
        "reference_preparation_seconds_observed_sum", "reference_preparation_seconds_sum"
    ),
    "native_runtime_by_stage.csv": (
        "observed_first_role_wall_seconds_observed_sum", "observed_first_role_wall_seconds_sum",
        "reference_preparation_seconds_observed_sum", "reference_preparation_seconds_sum"
    ),
}

# JSON numeric paths are explicit.  '*' matches exactly one list index or key.
_TIMING_KEYS = ("mean_seconds", "median_seconds", "p95_seconds", "minimum_seconds", "maximum_seconds")
_RETRIEVAL_METRICS = ("mean_recall_at_5", "mrr_at_5", "complete_evidence_set_coverage_rate_at_5")
_CLASSIFIER_METRICS = ("accuracy", "macro_precision", "macro_recall", "macro_f1")
JSON_MEASUREMENTS = {
    "analysis_summary.json": (
        "/headline_planner_rows/*/percent",
        *(f"/timing_all_terminal/*/{key}" for key in _TIMING_KEYS),
        *(f"/retrieval/reported_route_metrics/*/{key}" for key in _RETRIEVAL_METRICS),
        *(f"/classifier/observed/*/{key}" for key in _CLASSIFIER_METRICS),
    ),
    "retrieval_analysis_status.json": tuple(
        f"/summary/reported_route_metrics/*/{key}" for key in _RETRIEVAL_METRICS
    ),
    "classifier_summary.json": tuple(f"/*/{key}" for key in _CLASSIFIER_METRICS),
    "classifier_analysis_status.json": tuple(f"/observed/*/{key}" for key in _CLASSIFIER_METRICS),
    "analysis_input_manifest.json": tuple(
        f"/classifier_status/observed/*/{key}" for key in _CLASSIFIER_METRICS
    ),
}
ENVIRONMENT_FIELDS = {
    "bootstrap_settings.json": ("/numpy_version",),
    "analysis_input_manifest.json": ("/bootstrap_settings/numpy_version",),
}
_SVG = "{http://www.w3.org/2000/svg}"
_XLINK = "{http://www.w3.org/1999/xlink}"
_NUMBER = r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?"


def comparison_policy() -> dict[str, Any]:
    """Return the predeclared default rules for inclusion in verification config."""
    return {
        "schema_version": "step36-comparison-policy-2",
        "rtol": 1e-10,
        "atol": 1e-12,
        "csv_measurement_columns": {key: list(value) for key, value in CSV_MEASUREMENTS.items()},
        "json_measurement_fields": {key: list(value) for key, value in JSON_MEASUREMENTS.items()},
        "json_environment_fields": {key: list(value) for key, value in ENVIRONMENT_FIELDS.items()},
        "discrete_policy": "Exact paths, CSV schema and row order, labels, statuses, IDs, counts, denominators, memberships and draws; no imputation.",
        "npz_policy": "Exact member names, dtype, shape and array values; ZIP headers/timestamps excluded.",
        "manifest_policy": "Each output manifest hash is validated against its own file; ID binds to input-manifest bytes, and summary locations bind to ID.",
        "svg_policy": "Parse SVG and require matching figure source tables. Verify Unicode/glyph-index references against actual font outlines, labels, populations and chart geometry (bars1e-4 units, classifier CI/points1e-7 units) when presentation differs. If semantic glyph decoding is unavailable, permit only exact complete vector/presentation identity apart from metadata, with passing source comparisons; report equality-only evidence explicitly. Changed vectors cannot use that route.",
        "svg_implementation_correction": "Font-specific glyph indices are not Unicode codepoints. This correction follows the saved Step36 font-decoding failure; numeric tolerances, frozen analysis code and scientific results are unchanged.",
        "review_provenance": "One assisted team review; original independent raters and agreement unavailable. Preserve the recorded status without inventing ratings.",
    }


def _config(config: Mapping[str, Any] | None) -> dict[str, Any]:
    supplied = dict(config or {})
    known = {"rtol", "atol", "json_environment_fields", "json_path_fields", "original_root", "reproduced_root"}
    unknown = set(supplied) - known
    if unknown:
        raise ValueError("Unknown comparison config fields: " + ", ".join(sorted(unknown)))
    result = {"rtol": 1e-10, "atol": 1e-12, **supplied}
    for key in ("rtol", "atol"):
        if isinstance(result[key], bool) or not isinstance(result[key], (int, float)) or not math.isfinite(result[key]) or result[key] < 0:
            raise ValueError(f"{key} must be finite and nonnegative")
    extra_environment = supplied.get("json_environment_fields", {})
    if not isinstance(extra_environment, Mapping):
        raise ValueError("json_environment_fields must be a filename-to-JSON-pointer mapping")
    environment = {key: list(value) for key, value in ENVIRONMENT_FIELDS.items()}
    for filename, pointers in extra_environment.items():
        if not isinstance(pointers, (tuple, list)):
            raise ValueError("json_environment_fields values must be lists of exact JSON pointers")
        environment.setdefault(filename, []).extend(pointers)
    result["json_environment_fields"] = environment
    result.setdefault("json_path_fields", {})
    for mapping_key in ("json_environment_fields", "json_path_fields"):
        if not isinstance(result[mapping_key], Mapping):
            raise ValueError(mapping_key + " must be a filename-to-JSON-pointer mapping")
        for filename, pointers in result[mapping_key].items():
            if not isinstance(filename, str) or not isinstance(pointers, (tuple, list)) or not all(isinstance(p, str) and p.startswith("/") and "*" not in p for p in pointers):
                raise ValueError(mapping_key + " requires exact JSON pointers without wildcards")
    if result["json_path_fields"] and not all(result.get(key) for key in ("original_root", "reproduced_root")):
        raise ValueError("Named relocatable path fields require both roots")
    return result


def _sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _row(name: str, method: str, errors: list[str], notes: list[str] | None = None) -> dict[str, Any]:
    return {
        "filepath": name,
        "method": method,
        "status": "failed" if errors else "passed",
        "details": json.dumps({"errors": errors[:20], "error_count": len(errors), "notes": notes or []}, ensure_ascii=False, sort_keys=True),
    }


def _inventory(folder: Path) -> set[str]:
    if not folder.is_dir():
        raise ValueError(f"Analysis folder is missing: {folder}")
    files = set()
    for path in folder.rglob("*"):
        if path.is_symlink():
            raise ValueError(f"Analysis outputs must not contain symlinks: {path.relative_to(folder)}")
        if path.is_file():
            files.add(path.relative_to(folder).as_posix())
    return files


def _json(path: Path) -> Any:
    def unique_pairs(pairs):
        result = {}
        for key, value in pairs:
            if key in result:
                raise ValueError("Duplicate JSON key: " + key)
            result[key] = value
        return result
    return json.loads(path.read_text(encoding="utf-8"), object_pairs_hook=unique_pairs,
                      parse_constant=lambda token: (_ for _ in ()).throw(ValueError("Nonfinite JSON value: " + token)))


def _pointer(parts: tuple[str, ...]) -> str:
    return "/" + "/".join(part.replace("~", "~0").replace("/", "~1") for part in parts)


def _matches(pattern: str, parts: tuple[str, ...]) -> bool:
    decoded = tuple(p.replace("~1", "/").replace("~0", "~") for p in pattern.split("/")[1:])
    return len(decoded) == len(parts) and all(wanted == "*" or wanted == actual for wanted, actual in zip(decoded, parts))


def _close(a: Any, b: Any, config: dict[str, Any]) -> bool:
    if isinstance(a, bool) or isinstance(b, bool):
        return False
    try:
        left, right = float(a), float(b)
    except (TypeError, ValueError, OverflowError):
        return False
    return math.isfinite(left) and math.isfinite(right) and math.isclose(left, right, rel_tol=config["rtol"], abs_tol=config["atol"])


def _relocated(a: str, b: str, config: dict[str, Any]) -> bool:
    # Pure lexical relocation: no resolving arbitrary paths or replacing substrings.
    try:
        left = PurePosixPath(a).relative_to(PurePosixPath(str(config["original_root"])))
        right = PurePosixPath(b).relative_to(PurePosixPath(str(config["reproduced_root"])))
    except (ValueError, KeyError):
        return False
    return left == right and ".." not in left.parts


def _compare_json(a: Any, b: Any, filename: str, config: dict[str, Any], parts: tuple[str, ...] = (), errors: list[str] | None = None, notes: list[str] | None = None):
    errors = [] if errors is None else errors
    notes = [] if notes is None else notes
    pointer = _pointer(parts)
    if isinstance(a, dict) and isinstance(b, dict):
        if set(a) != set(b):
            errors.append(f"{pointer}: JSON keys differ; missing={sorted(set(a)-set(b))}, unexpected={sorted(set(b)-set(a))}")
        for key in sorted(set(a) & set(b)):
            _compare_json(a[key], b[key], filename, config, parts + (key,), errors, notes)
    elif isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            errors.append(f"{pointer}: list lengths differ: {len(a)} != {len(b)}")
        for i, (left, right) in enumerate(zip(a, b)):
            _compare_json(left, right, filename, config, parts + (str(i),), errors, notes)
    elif type(a) is type(b) and a == b:
        pass
    elif pointer in config["json_environment_fields"].get(filename, ()):
        if isinstance(a, str) and isinstance(b, str) and a and b:
            notes.append(f"Allowed environment metadata {pointer}: {a!r} -> {b!r}")
        else:
            errors.append(f"{pointer}: environment metadata must remain a nonempty version string")
    elif pointer in config["json_path_fields"].get(filename, ()):
        if isinstance(a, str) and isinstance(b, str) and _relocated(a, b, config):
            notes.append(f"Allowed explicit root relocation {pointer}: {a!r} -> {b!r}")
        else:
            errors.append(f"{pointer}: named path is not an exact root relocation")
    elif any(_matches(pattern, parts) for pattern in JSON_MEASUREMENTS.get(filename, ())) and _close(a, b, config):
        notes.append(f"Within numeric tolerance {pointer}: {a!r} -> {b!r}")
    else:
        errors.append(f"{pointer}: {a!r} != {b!r}")
    return errors, notes


def _read_csv(path: Path) -> tuple[list[str], list[list[str]]]:
    with path.open(encoding="utf-8-sig", newline="") as stream:
        rows = list(csv.reader(stream))
    if not rows or not rows[0] or len(rows[0]) != len(set(rows[0])):
        raise ValueError("CSV header is absent or duplicated")
    width = len(rows[0])
    if any(len(row) != width for row in rows[1:]):
        raise ValueError("CSV has a row with a different width from its schema")
    return rows[0], rows[1:]


def _compare_csv(left: Path, right: Path, name: str, config: dict[str, Any]):
    headers, a = _read_csv(left)
    other_headers, b = _read_csv(right)
    errors, notes = [], []
    if headers != other_headers:
        return [f"CSV schema/order differs: {headers!r} != {other_headers!r}"], notes
    if len(a) != len(b):
        errors.append(f"Row count differs: {len(a)} != {len(b)}")
    tolerant_cells = 0
    for index, (row_a, row_b) in enumerate(zip(a, b), start=2):
        for field, value_a, value_b in zip(headers, row_a, row_b):
            # Blank vs zero/NA/null and all unlisted columns are deliberately exact.
            if value_a == value_b:
                if field in CSV_MEASUREMENTS.get(name, ()) and value_a and not _close(value_a, value_b, config):
                    errors.append(f"row {index}, {field}: invalid/nonfinite measurement {value_a!r}")
            elif field in CSV_MEASUREMENTS.get(name, ()) and value_a and value_b and _close(value_a, value_b, config):
                tolerant_cells += 1
            else:
                errors.append(f"row {index}, {field}: {value_a!r} != {value_b!r}")
    notes.append(f"Exact CSV schema and row order; {len(a)} original rows; {tolerant_cells} differing measurement cells within rtol={config['rtol']}, atol={config['atol']}")
    return errors, notes


def _compare_npz(left: Path, right: Path):
    errors, notes = [], []
    with np.load(left, allow_pickle=False) as a, np.load(right, allow_pickle=False) as b:
        if len(a.files) != len(set(a.files)) or len(b.files) != len(set(b.files)):
            errors.append("NPZ contains duplicate array member names")
        if set(a.files) != set(b.files):
            errors.append(f"NPZ member names differ: {a.files!r} != {b.files!r}")
        for name in sorted(set(a.files) & set(b.files)):
            x, y = a[name], b[name]
            if x.dtype != y.dtype or x.shape != y.shape or not np.array_equal(x, y):
                errors.append(f"NPZ {name}: dtype/shape/value mismatch ({x.dtype}, {x.shape}) vs ({y.dtype}, {y.shape})")
            else:
                notes.append(f"Exact array {name}: dtype={x.dtype}, shape={list(x.shape)}, elements={x.size}")
    if left.read_bytes() != right.read_bytes() and not errors:
        notes.append("Archive bytes differ; decoded arrays are exactly equal (ZIP container metadata is excluded)")
    return errors, notes


def _manifest_errors(folder: Path, inventory: set[str]) -> tuple[list[str], dict[str, Any] | None]:
    errors = []
    if "output_manifest.json" not in inventory:
        return ["Required output_manifest.json is absent"], None
    document = _json(folder / "output_manifest.json")
    if not isinstance(document, dict) or set(document) != {"schema_version", "analysis_id", "files"}:
        return ["Unexpected output manifest schema"], document
    files = document["files"]
    if not isinstance(files, dict):
        return ["Output manifest files is not a mapping"], document
    expected = set(files) | {"output_manifest.json"}
    if inventory != expected:
        errors.append(f"Manifest inventory mismatch: missing={sorted(expected-inventory)}, unexpected={sorted(inventory-expected)}")
    for name, expected_sha in files.items():
        relative = PurePosixPath(name)
        if relative.is_absolute() or ".." in relative.parts or "\\" in name or ":" in name:
            errors.append(f"Unsafe manifest path: {name!r}")
        elif name in inventory and (not isinstance(expected_sha, str) or _sha(folder / name) != expected_sha):
            errors.append(f"Manifest hash mismatch: {name}")
    if "analysis_input_manifest.json" in inventory:
        identity = _sha(folder / "analysis_input_manifest.json")
        if document.get("analysis_id") != identity:
            errors.append("analysis_id is not the SHA256 of analysis_input_manifest.json")
        inputs = _json(folder / "analysis_input_manifest.json")
        # These are duplicated records in Step 35, not independent measurements.
        # Even allowed version metadata must agree inside one analysis run.
        for key, filename in (("bootstrap_settings", "bootstrap_settings.json"),
                              ("method_note", "analysis_method_note.json"),
                              ("classifier_status", "classifier_analysis_status.json")):
            if key in inputs and (filename not in inventory or inputs[key] != _json(folder / filename)):
                errors.append(f"Input manifest /{key} disagrees with {filename}")
    else:
        errors.append("Required analysis_input_manifest.json is absent")
    return errors, document


def _summary_binding(document: dict[str, Any], folder: Path) -> list[str]:
    errors = []
    if not (folder / "analysis_input_manifest.json").is_file():
        return ["Cannot bind summary without analysis_input_manifest.json"]
    identity = _sha(folder / "analysis_input_manifest.json")
    analysis_folder = "results/statistical_analysis/analysis_" + identity[:20]
    expected = {"analysis_id": identity, "input_manifest_sha256": identity, "analysis_folder": analysis_folder,
                "findings_path": analysis_folder + "/statistical_analysis_findings.md",
                "report_path": analysis_folder + "/analysis_report.html"}
    for key, value in expected.items():
        if document.get(key) != value:
            errors.append(f"{key} does not bind to this run's input manifest/analysis ID")
    return errors


def _csv_dicts(folder: Path, name: str) -> list[dict[str, str]]:
    fields, rows = _read_csv(folder / name)
    return [dict(zip(fields, row)) for row in rows]


@lru_cache(maxsize=None)
def _svg_font_path(postscript_name: str) -> str:
    """Locate the installed font named by a Matplotlib glyph ID, fail closed."""
    try:
        from matplotlib import font_manager, ft2font
    except ImportError as exc:
        raise ValueError("Matplotlib is required to verify SVG glyph outlines") from exc
    for entry in font_manager.fontManager.ttflist:
        try:
            font = ft2font.FT2Font(entry.fname)
        except (OSError, RuntimeError):
            continue
        if font.postscript_name == postscript_name:
            return str(entry.fname)
    raise ValueError("Cannot verify SVG glyph font: " + postscript_name)


def _svg_path_signature(path: ET.Element) -> tuple:
    """Compare actual outline coordinates exactly after its uniform scale.

    SVG path whitespace and 64-unit encoding are serialization choices.  No
    coordinate tolerance is used; unsupported glyph presentation fails closed.
    """
    if path.tag != _SVG + "path" or set(path.attrib) - {"id", "d", "transform"}:
        raise ValueError("SVG glyph definition has unsupported presentation")
    transform = path.get("transform", "").strip()
    scale = Fraction(1)
    if transform:
        match = re.fullmatch(r"scale\(\s*(" + _NUMBER + r")\s*\)", transform)
        if not match:
            raise ValueError("SVG glyph definition has unsupported transform")
        scale = Fraction(match.group(1))
        if scale <= 0:
            raise ValueError("SVG glyph definition has nonpositive scale")
    data = path.get("d", "")
    tokens = re.findall(_NUMBER + r"|[MLQCz]", data)
    if re.sub(_NUMBER + r"|[MLQCz]|[\s,]+", "", data):
        raise ValueError("SVG glyph outline has unsupported path commands")
    return tuple(token if token in {"M", "L", "Q", "C", "z"} else Fraction(token)*scale
                 for token in tokens)


@lru_cache(maxsize=None)
def _svg_glyph_candidates(postscript_name: str, suffix: int, signature: tuple) -> frozenset[str]:
    """Bind either historic codepoint IDs or newer glyph-index IDs to outlines.

    An ID suffix and source comment are insufficient evidence: the referenced
    vector outline must equal the named installed font's actual glyph.  The
    inverse cmap also handles glyph-index IDs without assuming an offset.
    """
    from matplotlib import _path, ft2font
    from matplotlib.path import Path as MplPath
    font = ft2font.FT2Font(_svg_font_path(postscript_name))
    font.set_size(100, 72)  # Matplotlib TextToPath.FONT_SCALE and DPI.
    cmap = font.get_charmap()
    possible = {codepoint for codepoint, index in cmap.items() if index == suffix}
    if suffix in cmap:
        possible.add(suffix)
    flags = ft2font.LoadFlags.NO_HINTING if hasattr(ft2font, "LoadFlags") else ft2font.LOAD_NO_HINTING
    candidates = set()
    for codepoint in possible:
        font.load_glyph(cmap[codepoint], flags=flags)
        vertices, codes = font.get_path()
        data = _path.convert_to_string(MplPath(vertices*64, codes), None, None, False, None,
                                       6, [b"M", b"L", b"Q", b"C", b"z"], False).decode("ascii")
        expected = ET.Element(_SVG + "path", d=data, transform="scale(0.015625)")
        if _svg_path_signature(expected) == signature:
            candidates.add(chr(codepoint))
    return frozenset(candidates)


class _SvgGlyphResolver:
    """Document-wide ID lookup, also used when validating an axis/tick subtree."""

    def __init__(self, root: ET.Element):
        self.definitions = {element.get("id"): element for element in root.iter() if element.get("id")}
        self.candidates: dict[str, frozenset[str]] = {}

    def resolve(self, href: str) -> frozenset[str]:
        if href not in self.candidates:
            match = re.fullmatch(r"#([A-Za-z][A-Za-z0-9_\-]*)-([0-9a-fA-F]+)", href)
            definition = self.definitions.get(href[1:])
            if not match or definition is None:
                raise ValueError("Cannot decode an SVG text glyph reference: " + href)
            signature = _svg_path_signature(definition)
            candidates = _svg_glyph_candidates(match.group(1), int(match.group(2), 16), signature)
            if not candidates:
                raise ValueError("SVG text glyph outline does not match its font/codepoint or glyph index: " + href)
            self.candidates[href] = candidates
        return self.candidates[href]


def _svg_labels(root: ET.Element, glyph_resolver: _SvgGlyphResolver | None = None) -> list[str]:
    """Read text or independently verified glyph outlines; cross-check comments."""
    labels = []
    resolver = glyph_resolver or _SvgGlyphResolver(root)
    for element in root.iter():
        if element.tag == _SVG + "text":
            labels.append("".join(element.itertext()))
        elif element.tag == _SVG + "g" and re.fullmatch(r"text_\d+", element.get("id", "")):
            if any(child.tag == _SVG + "text" for child in element.iter()):
                continue
            glyphs = [resolver.resolve(child.get(_XLINK + "href", child.get("href", "")))
                      for child in element.iter(_SVG + "use")]
            comments = [str(child.text).strip() for child in element if child.tag is ET.Comment]
            if comments:
                # A comment can select among true cmap aliases only after each
                # glyph outline has independently established those candidates.
                if len(comments) != 1 or len(comments[0]) != len(glyphs) or any(
                        character not in candidates for character, candidates in zip(comments[0], glyphs)):
                    raise ValueError(f"SVG text comment disagrees with rendered glyphs: {comments!r}")
                rendered = comments[0]
            else:
                if any(len(candidates) != 1 for candidates in glyphs):
                    raise ValueError("SVG glyph outline has ambiguous Unicode mapping")
                rendered = "".join(next(iter(candidates)) for candidates in glyphs)
            if not rendered:
                raise ValueError("SVG text group has no rendered text")
            labels.append(rendered)
    return labels


def _parse_svg(path: Path) -> ET.Element:
    raw = path.read_bytes()
    if re.search(rb"<!ENTITY\b|<script\b|<foreignObject\b|<image\b", raw, re.I):
        raise ValueError("SVG has entity/script/foreign/raster content")
    root = ET.fromstring(raw, parser=ET.XMLParser(target=ET.TreeBuilder(insert_comments=True)))
    if root.tag != _SVG + "svg" or next(root.iter(_SVG + "path"), None) is None:
        raise ValueError("Figure is not a populated vector SVG")
    all_ids = [element.get("id") for element in root.iter() if element.get("id")]
    ids = set(all_ids)
    if len(ids) != len(all_ids):
        raise ValueError("SVG has duplicate element IDs")
    for element in root.iter():
        if isinstance(element.tag, str) and element.tag.rsplit("}", 1)[-1].lower() in ("image", "script", "foreignobject"):
            raise ValueError("SVG has script/foreign/raster content")
        for key, value in element.attrib.items():
            if key in ("href", _XLINK + "href") and (not value.startswith("#") or value[1:] not in ids):
                raise ValueError("SVG has an external or unresolved reference")
            if key == "style" and re.search(r"(?:display\s*:\s*none|visibility\s*:\s*hidden|opacity\s*:\s*0(?:;|$))", value):
                raise ValueError("SVG hides visual content")
    return root


def _single_label(element: ET.Element, glyph_resolver: _SvgGlyphResolver | None = None) -> str:
    values = _svg_labels(element, glyph_resolver)
    if len(values) != 1:
        raise ValueError("Expected exactly one tick label")
    return values[0]


def _bars_from_axis(axis: ET.Element, glyph_resolver: _SvgGlyphResolver | None = None) -> list[float]:
    ticks = []
    for element in axis.iter(_SVG + "g"):
        if re.fullmatch(r"ytick_\d+", element.get("id", "")):
            label = _single_label(element, glyph_resolver).replace("−", "-")
            if not re.fullmatch(_NUMBER, label):
                raise ValueError("Bar chart has a nonnumeric y tick")
            tick_mark = next((use for use in element.iter(_SVG + "use") if "y" in use.attrib), None)
            if tick_mark is None:
                raise ValueError("Bar chart tick has no coordinate")
            ticks.append((float(tick_mark.attrib["y"]), float(label)))
    if len(ticks) < 2 or len({p[0] for p in ticks}) != len(ticks):
        raise ValueError("Bar chart needs distinct calibrated y ticks")
    first, last = ticks[0], ticks[-1]
    slope = (last[1] - first[1]) / (last[0] - first[0])
    intercept = first[1] - first[0] * slope
    if slope >= 0 or any(abs(slope * y + intercept - value) > 1e-4 for y, value in ticks):
        raise ValueError("Bar chart y axis is not the expected linear ascending scale")
    rectangles = []
    for group in axis:
        if group.tag != _SVG + "g" or not re.fullmatch(r"patch_\d+", group.get("id", "")):
            continue
        path = next(group.iter(_SVG + "path"), None)
        if path is None:
            continue
        style = path.get("style", "")
        fill = re.search(r"(?:^|;)\s*fill\s*:\s*([^;]+)", style)
        if not fill or fill.group(1).strip() in ("none", "#ffffff", "white"):
            continue
        commands = re.findall(r"[A-Za-z]", path.get("d", ""))
        values = [float(value) for value in re.findall(_NUMBER, path.get("d", ""))]
        if commands != ["M", "L", "L", "L", "z"] or len(values) != 8:
            raise ValueError("Bar chart patch is not a rectangular bar")
        points = list(zip(values[::2], values[1::2]))
        if len({p[0] for p in points}) != 2 or len({p[1] for p in points}) > 2:
            raise ValueError("Bar chart has a nonrectangular data patch")
        baseline, top = max(p[1] for p in points), min(p[1] for p in points)
        if abs(slope * baseline + intercept) > 1e-4:
            raise ValueError("Bar does not start at zero")
        rectangles.append((min(p[0] for p in points), slope * top + intercept))
    return [value for _, value in sorted(rectangles)]


def _classifier_geometry(axis: ET.Element, selected: list[dict[str, str]], glyph_resolver: _SvgGlyphResolver | None = None) -> list[str]:
    """Calibrate a difference plot from its actual ticks and inspect line/points."""
    errors, ticks, category_positions = [], [], {}
    names = {"logistic_regression_minus_majority": "Logistic − majority",
             "neural_minus_majority": "Neural − majority",
             "neural_minus_logistic_regression": "Neural − logistic"}
    for group in axis.iter(_SVG + "g"):
        identifier = group.get("id", "")
        if re.fullmatch(r"xtick_\d+", identifier):
            label = _single_label(group, glyph_resolver).replace("−", "-")
            tick_mark = next((use for use in group.iter(_SVG + "use") if "x" in use.attrib), None)
            if not re.fullmatch(_NUMBER, label) or tick_mark is None:
                raise ValueError("Classifier difference plot has an uncalibrated x tick")
            ticks.append((float(tick_mark.attrib["x"]), float(label)))
        elif re.fullmatch(r"ytick_\d+", identifier):
            label = _single_label(group, glyph_resolver)
            tick_mark = next((use for use in group.iter(_SVG + "use") if "y" in use.attrib), None)
            if label in category_positions or tick_mark is None:
                raise ValueError("Classifier difference plot has duplicate/unpositioned category ticks")
            category_positions[label] = float(tick_mark.attrib["y"])
    if len(ticks) < 2 or len({x for x, _ in ticks}) != len(ticks):
        raise ValueError("Classifier difference plot needs distinct calibrated x ticks")
    slope = (ticks[-1][1] - ticks[0][1]) / (ticks[-1][0] - ticks[0][0])
    intercept = ticks[0][1] - slope * ticks[0][0]
    if slope <= 0 or any(abs(slope*x + intercept-value) > 1e-7 for x, value in ticks):
        raise ValueError("Classifier plot x ticks do not define the expected linear difference scale")
    if set(category_positions) != set(names.values()):
        raise ValueError("Classifier plot does not have exactly the three prespecified contrast labels")
    # Values below are SVG rounding checks, not a waiver for numeric source data.
    # Source endpoints/estimates separately use the stricter declared tolerance.
    line_values, point_values, zero_lines = {}, {}, 0
    for group in axis:
        if group.tag != _SVG + "g" or not re.fullmatch(r"line2d_\d+", group.get("id", "")):
            continue
        paths = [element for element in group if element.tag == _SVG + "path"]
        uses = [element for element in group.iter(_SVG + "use") if "x" in element.attrib and "y" in element.attrib]
        if paths and uses:
            raise ValueError("Classifier plot has an unexpected mixed line/marker data object")
        if paths:
            if len(paths) != 1:
                raise ValueError("Classifier plot has an unexpected multiple-path data object")
            path = paths[0]
            if re.findall(r"[A-Za-z]", path.get("d", "")) != ["M", "L"]:
                raise ValueError("Classifier plot confidence interval is not a straight line")
            values = [float(number) for number in re.findall(_NUMBER, path.get("d", ""))]
            if len(values) != 4:
                raise ValueError("Classifier plot line has unexpected coordinates")
            x1, y1, x2, y2 = values
            if abs(x1-x2) < 1e-6 and abs(y1-y2) > 1e-6:
                zero_lines += 1
                if abs(slope*x1 + intercept) > 1e-7:
                    errors.append("Classifier difference reference line is not at zero")
                continue
            if abs(y1-y2) > 1e-6:
                raise ValueError("Classifier confidence interval is not horizontal")
            labels = [label for label, y in category_positions.items() if abs(y-y1) < 1e-4]
            if len(labels) != 1 or labels[0] in line_values:
                raise ValueError("Classifier interval is detached from its unique contrast label")
            line_values[labels[0]] = sorted((slope*x1+intercept, slope*x2+intercept))
        elif uses:
            if len(uses) != 1:
                raise ValueError("Classifier plot has an unexpected multiple-marker data object")
            marker = uses[0]
            x, y = float(marker.attrib["x"]), float(marker.attrib["y"])
            labels = [label for label, coordinate in category_positions.items() if abs(coordinate-y) < 1e-4]
            if len(labels) != 1 or labels[0] in point_values:
                raise ValueError("Classifier estimate point is detached from its unique contrast label")
            point_values[labels[0]] = slope*x+intercept
        else:
            raise ValueError("Classifier plot has an empty/unrecognized data object")
    if set(line_values) != set(names.values()) or set(point_values) != set(names.values()) or zero_lines != 1:
        errors.append("Classifier plot must have one interval and estimate per contrast and one zero-reference line")
    for row in selected:
        label = names[row["model_or_contrast"]]
        if label in line_values and any(abs(actual-float(row[key])) > 1e-7 for actual, key in zip(line_values[label], ("lower_95", "upper_95"))):
            errors.append("Classifier CI line geometry differs from source endpoints: " + row["model_or_contrast"])
        if label in point_values and abs(point_values[label]-float(row["estimate"])) > 1e-7:
            errors.append("Classifier point geometry differs from source estimate: " + row["model_or_contrast"])
    return errors


def _validate_known_figure(root: ET.Element, folder: Path, name: str, glyph_resolver: _SvgGlyphResolver | None = None) -> tuple[list[str], list[str]]:
    errors, notes = [], []
    glyph_resolver = glyph_resolver or _SvgGlyphResolver(root)
    labels = _svg_labels(root, glyph_resolver)
    axes = [element for element in root.iter(_SVG + "g") if re.fullmatch(r"axes_\d+", element.get("id", ""))]
    if name == "figures/planner_execution.svg":
        expected_titles = ("Response format", "Workflow completion")
        expected_metrics = ("strict_format_valid", "designated_workflow_completed")
        required = ["Saved comparison: 200 matched profiles, four planners", "Outcomes out of 200", *expected_titles]
        rows = _csv_dicts(folder, "planner_summary.csv")
        if len(axes) != 2:
            return ["Expected two planner execution panels"], notes
        for axis, metric, title in zip(axes, expected_metrics, expected_titles):
            selected = [row for row in rows if row["population"] == "all_planner" and row["metric"] == metric]
            if {row["planner"] for row in selected} != {"1", "2", "3", "4"} or len(selected) != 4 or any(row["denominator"] != "200" or row["families"] != "200" for row in selected):
                errors.append("Execution figure source population/denominators differ from four matched planners with 200 outcomes each")
                continue
            by_planner = {row["planner"]: row for row in selected}
            values = [float(by_planner[str(planner)]["numerator"]) for planner in range(1, 5)]
            bar_values = _bars_from_axis(axis, glyph_resolver)
            if len(bar_values) != 4 or any(abs(a-b) > 1e-4 for a, b in zip(values, bar_values)):
                errors.append(f"{title}: plotted bar geometry differs from exact source counts")
            axis_labels = _svg_labels(axis, glyph_resolver)
            for planner, value in enumerate(values, 1):
                if f"Planner {planner}" not in axis_labels or str(int(value)) not in axis_labels:
                    errors.append(f"{title}: missing rendered planner/count label")
            if title not in axis_labels:
                errors.append(f"Missing panel label: {title}")
        notes.append("Execution panels checked against planner_summary.csv: numerator, denominator=200, family membership population and rendered labels")
    elif name == "figures/planner_runtime.svg":
        required = ["Median end-to-end time (seconds)", "All terminal workflows, including failures (200 per planner)"]
        rows = [row for row in _csv_dicts(folder, "runtime_resource_summary.csv") if row["population"] == "all_terminal"]
        if len(axes) != 1 or len(rows) != 4 or {row["planner"] for row in rows} != {"1", "2", "3", "4"} or any(row["outcomes"] != "200" or row["measured"] != "200" or row["missing"] != "0" for row in rows):
            return ["Runtime figure source population differs from four fully measured all-terminal sets of 200"], notes
        by_planner = {row["planner"]: row for row in rows}
        values = [float(by_planner[str(planner)]["median_seconds"]) for planner in range(1, 5)]
        bar_values = _bars_from_axis(axes[0], glyph_resolver)
        if len(bar_values) != 4 or any(abs(a-b) > 1e-4 for a, b in zip(values, bar_values)):
            errors.append("Runtime plotted bar geometry differs from source medians")
        for planner, value in enumerate(values, 1):
            if f"Planner {planner}" not in labels or f"{value:.2f} s" not in labels:
                errors.append("Runtime figure is missing rendered planner/median labels")
        notes.append("Runtime panel checked against runtime_resource_summary.csv: all_terminal population, measured denominator, medians and rendered labels")
    elif name == "figures/classifier_macro_f1_differences.svg":
        required = ["Macro-F1 difference (0–1 scale)", "Paired exercise-group bootstrap: individual 95% intervals",
                    "Logistic − majority", "Neural − majority", "Neural − logistic"]
        selected = [row for row in _csv_dicts(folder, "bootstrap_intervals.csv")
                    if row["population"] == "classifier_test" and row["metric"] == "macro_f1" and "_minus_" in row["model_or_contrast"]]
        contrasts = {"logistic_regression_minus_majority", "neural_minus_majority", "neural_minus_logistic_regression"}
        population = [row for row in _csv_dicts(folder, "analysis_populations.csv") if row["population"] == "classifier_test"]
        settings = _json(folder / "bootstrap_settings.json")
        groups = settings["groups"]["classifier_test"]
        if len(axes) != 1 or len(selected) != 3 or {row["model_or_contrast"] for row in selected} != contrasts:
            return ["Classifier figure lacks exactly three prespecified macro-F1 contrasts in one panel"], notes
        if not population or len({row["record_id"] for row in population}) != len(population) or any(not row.get("target_label") for row in population):
            errors.append("Classifier figure source population has missing/duplicate record IDs or missing class labels")
        if sorted(set(row["group_id"] for row in population)) != groups:
            errors.append("Classifier plot population group membership differs from bootstrap settings")
        for row in selected:
            if (int(row["profiles"]) != len(population) or int(row["groups"]) != len(groups) or
                    int(row["resamples"]) != settings["resamples"] or row["unit"] != "raw_0_to_1_score_difference" or row["status"] != "computed"):
                errors.append("Classifier interval population/group denominator, resampling or unit differs from source settings")
        errors.extend(_classifier_geometry(axes[0], selected, glyph_resolver))
        notes.append("Classifier CI endpoints and estimate points calibrated from actual SVG axes against bootstrap_intervals.csv; contrast labels, zero-reference, record IDs, class labels and group memberships checked")
    else:
        # Future figure formats need their own semantic validator before layout
        # differences may pass.  The caller only permits exact vector content.
        return [], ["Unrecognized figure: exact SVG content required apart from metadata"]
    for label in required:
        if label not in labels:
            errors.append("Missing required rendered figure label: " + label)
    return errors, notes


def _svg_without_metadata(root: ET.Element):
    def encode(element):
        if element.tag == _SVG + "metadata":
            return None
        return (str(element.tag), tuple(sorted(element.attrib.items())), (element.text or "").strip(),
                tuple(encoded for child in element if (encoded := encode(child)) is not None))
    return encode(root)


def _compare_svg(left: Path, right: Path, name: str, source_status: dict[str, str]):
    a, b = _parse_svg(left), _parse_svg(right)
    errors, notes = [], []
    dependencies = {"figures/planner_execution.svg": ("planner_summary.csv", "analysis_populations.csv"),
                    "figures/planner_runtime.svg": ("runtime_resource_summary.csv", "analysis_populations.csv"),
                    "figures/classifier_macro_f1_differences.svg": ("bootstrap_intervals.csv", "analysis_populations.csv", "bootstrap_settings.json")}
    if name in dependencies:
        for dependency in dependencies[name]:
            if source_status.get(dependency) != "passed":
                errors.append("Figure source did not pass comparison: " + dependency)
    left_glyphs, right_glyphs = _SvgGlyphResolver(a), _SvgGlyphResolver(b)
    try:
        left_labels, right_labels = _svg_labels(a, left_glyphs), _svg_labels(b, right_glyphs)
    except ValueError as exc:
        # A new font/shaper may use glyph IDs or ligatures unavailable locally.
        # Equality of the complete vector tree is independent reproduction
        # evidence; no changed glyph, bar or CI geometry can use this fallback.
        if name in dependencies and not errors and _svg_without_metadata(a) == _svg_without_metadata(b):
            return [], ["Exact vector/presentation content matches the preserved original apart from metadata; all figure source dependencies passed. "
                        "Semantic glyph decoding unavailable: " + str(exc)]
        raise
    if left_labels != right_labels:
        errors.append("Rendered SVG labels/order differ")
    if name in dependencies:
        for label, root, folder, glyphs in (("original", a, left.parent.parent, left_glyphs), ("reproduced", b, right.parent.parent, right_glyphs)):
            validation, evidence = _validate_known_figure(root, folder, name, glyphs)
            errors.extend(f"{label}: {message}" for message in validation)
            notes.extend(f"{label}: {message}" for message in evidence)
        if left.read_bytes() != right.read_bytes() and not errors:
            notes.append("Renderer metadata/layout differs; vector content, actual labels, populations and source plotted values validated")
    elif _svg_without_metadata(a) != _svg_without_metadata(b):
        errors.append("Unrecognized SVG has changed vector/presentation content; semantic validator required")
    return errors, notes


def compare_outputs(original_folder: str | Path, reproduced_folder: str | Path,
                    config: Mapping[str, Any] | None = None) -> list[dict[str, Any]]:
    """Compare two analysis folders read-only; return per-file CSV-ready rows.

    Comparison failures are rows with status ``failed``.  Bad config or absent
    folders raise ValueError.  Malformed individual files are reported as failures
    so one bad output does not suppress comparison of the remaining outputs.
    """
    settings = _config(config)
    original, reproduced = Path(original_folder), Path(reproduced_folder)
    inventory_a, inventory_b = _inventory(original), _inventory(reproduced)
    rows, source_status = [], {}
    manifests, manifest_failures = {}, []
    for label, folder, inventory in (("original", original, inventory_a), ("reproduced", reproduced, inventory_b)):
        try:
            errors, manifests[label] = _manifest_errors(folder, inventory)
        except Exception as exc:
            errors, manifests[label] = [f"{type(exc).__name__}: {exc}"], None
        manifest_failures.extend(f"{label}: {error}" for error in errors)
    missing = sorted(inventory_a - inventory_b)
    unexpected = sorted(inventory_b - inventory_a)
    # One explicit row per missing/unexpected file (the exact inventory is data).
    for name in missing:
        rows.append(_row(name, "exact_relative_filepath", ["Required original output is missing from reproduction"]))
        source_status[name] = "failed"
    for name in unexpected:
        rows.append(_row(name, "exact_relative_filepath", ["Unexpected output absent from original inventory"]))
        source_status[name] = "failed"
    common = inventory_a & inventory_b
    for name in sorted(common, key=lambda filename: (filename.endswith(".svg"), filename)):
        left, right = original / name, reproduced / name
        suffix = left.suffix.lower()
        method, errors, notes = "exact_bytes", [], []
        try:
            if name == "output_manifest.json":
                method = "manifest_inventory_and_local_hash_integrity"
                errors.extend(manifest_failures)
                a, b = manifests["original"], manifests["reproduced"]
                if a is not None and b is not None:
                    if a.get("schema_version") != b.get("schema_version"):
                        errors.append("Manifest schema versions differ")
                    if set(a.get("files", {})) != set(b.get("files", {})):
                        errors.append("Output manifest relative filepaths differ")
                notes.append("Per-file hashes checked independently; cross-run hashes are not substituted for semantic comparisons")
            elif suffix == ".csv":
                method = "exact_csv_schema_discrete_and_tolerant_named_measurements"
                errors, notes = _compare_csv(left, right, name, settings)
            elif suffix == ".npz":
                method = "exact_decoded_npz_arrays_dtype_shape_values"
                errors, notes = _compare_npz(left, right)
            elif suffix == ".json":
                method = "json_exact_except_declared_numeric_and_metadata_fields"
                a, b = _json(left), _json(right)
                if name == "analysis_summary.json":
                    errors.extend("original: " + error for error in _summary_binding(a, original))
                    errors.extend("reproduced: " + error for error in _summary_binding(b, reproduced))
                    bound = ("analysis_id", "input_manifest_sha256", "analysis_folder", "report_path", "findings_path")
                    if not errors:
                        for key in bound:
                            if a[key] != b[key]:
                                notes.append(f"Independently validated derived metadata /{key}: {a[key]!r} -> {b[key]!r}")
                        a = {key: value for key, value in a.items() if key not in bound}
                        b = {key: value for key, value in b.items() if key not in bound}
                comparison_errors, comparison_notes = _compare_json(a, b, name, settings)
                errors.extend(comparison_errors)
                notes.extend(comparison_notes)
            elif suffix == ".svg":
                method = "svg_vector_labels_populations_source_values_and_presentation"
                errors, notes = _compare_svg(left, right, name, source_status)
            elif left.read_bytes() != right.read_bytes():
                errors.append("File bytes differ; no normalization allowance is declared for this file")
        except Exception as exc:
            errors.append(f"{type(exc).__name__}: {exc}")
        row = _row(name, method, errors, notes)
        rows.append(row)
        source_status[name] = row["status"]
    if "output_manifest.json" not in common:
        rows.append(_row("[manifest_validation]", "manifest_inventory_and_local_hash_integrity", manifest_failures))
    return rows

step36_sources.reproduction_environment:
"""Create and record the independent analysis environment for Step 36.

This module intentionally imports only the Python standard library.  It never
loads an application model, training dependency, or an earlier environment.
"""
from __future__ import annotations

import datetime as _datetime
import importlib.metadata
import json
import os
from pathlib import Path
import platform
import re
import subprocess
import sys
import time
from urllib.parse import urlsplit, urlunsplit
import venv


_ANALYSIS_PACKAGES = {"numpy", "matplotlib", "nbclient", "nbformat", "ipykernel"}
_VERSION = re.compile(r"^[A-Za-z0-9][A-Za-z0-9.!+_-]*$")


def _now():
    return _datetime.datetime.now(_datetime.timezone.utc).isoformat()


def _write_json(path, value):
    Path(path).write_text(json.dumps(value, sort_keys=True, indent=2, allow_nan=False) + "\n", encoding="utf-8")


def _redact_url(match):
    raw = match.group(0)
    # Pip occasionally wraps a URL in punctuation. Keeping that punctuation is
    # cosmetic; removing user information and all query contents is essential.
    try:
        parts = urlsplit(raw)
        host = parts.hostname or ""
        if ":" in host:
            host = "[" + host + "]"
        if parts.port:
            host += ":" + str(parts.port)
        if parts.username is not None or parts.password is not None:
            host = "<redacted>@" + host
        return urlunsplit((parts.scheme, host, parts.path, "<redacted>" if parts.query else "", ""))
    except ValueError:
        return "<redacted-url>"


def redact(value):
    """Remove URL credentials/query values from persisted commands and logs."""
    if isinstance(value, str):
        return re.sub(r"(?:https?|ftp)://[^\s\"'<>]+", _redact_url, value)
    if isinstance(value, list):
        return [redact(item) for item in value]
    if isinstance(value, dict):
        return {key: redact(item) for key, item in value.items()}
    return value


def _parent_version(package, fallback=None):
    try:
        return importlib.metadata.version(package)
    except importlib.metadata.PackageNotFoundError:
        if fallback is not None:
            return fallback
        raise ValueError("The source analysis must supply a pinned " + package + " version.")


def analysis_requirements(numpy_version, matplotlib_version=None, ipykernel_version=None):
    """Build the five top-level pins; NumPy must come from the source manifest."""
    return {
        "numpy": str(numpy_version),
        "matplotlib": str(matplotlib_version or _parent_version("matplotlib")),
        "nbclient": "0.10.4",
        "nbformat": "5.10.4",
        "ipykernel": str(ipykernel_version or _parent_version("ipykernel", "6.30.1")),
    }


def _pins(requirements):
    if isinstance(requirements, dict):
        pins = {str(key).lower().replace("_", "-"): str(value) for key, value in requirements.items()}
    else:
        pins = {}
        for requirement in requirements:
            if not isinstance(requirement, str) or requirement.count("==") != 1:
                raise ValueError("Analysis requirements must be exact package==version pins.")
            name, version = requirement.split("==")
            name = name.lower().replace("_", "-")
            if name in pins:
                raise ValueError("Duplicate analysis requirement: " + name)
            pins[name] = version
    if set(pins) - _ANALYSIS_PACKAGES:
        raise ValueError("Only the five analysis/Jupyter top-level packages may be installed.")
    if "numpy" not in pins:
        raise ValueError("NumPy must be pinned to bootstrap_settings.numpy_version from the source manifest.")
    if "matplotlib" not in pins:
        pins["matplotlib"] = _parent_version("matplotlib")
    pins.setdefault("nbclient", "0.10.4")
    pins.setdefault("nbformat", "5.10.4")
    if "ipykernel" not in pins:
        pins["ipykernel"] = _parent_version("ipykernel", "6.30.1")
    for name, version in pins.items():
        if not _VERSION.fullmatch(version):
            raise ValueError("Invalid exact version for " + name)
    if pins["nbclient"] != "0.10.4" or pins["nbformat"] != "5.10.4":
        raise ValueError("The Step 36 runner pins nbclient==0.10.4 and nbformat==5.10.4.")
    return [name + "==" + pins[name] for name in sorted(pins)]


def isolated_environment(run_folder, python=None):
    """Environment shared by the external driver and its new notebook kernel."""
    run_folder = Path(run_folder).resolve()
    env = dict(os.environ)
    for name in ("PYTHONPATH", "PYTHONHOME", "IPYTHONDIR", "JUPYTER_PATH", "JUPYTER_CONFIG_PATH"):
        env.pop(name, None)
    env.update({
        "PYTHONNOUSERSITE": "1",
        "IPYTHONDIR": str(run_folder / "ipython"),
        "MPLCONFIGDIR": str(run_folder / "matplotlib_config"),
        "JUPYTER_DATA_DIR": str(run_folder / "jupyter_data"),
        "JUPYTER_CONFIG_DIR": str(run_folder / "jupyter_config"),
        "JUPYTER_RUNTIME_DIR": str(run_folder / "jupyter_runtime"),
        "JUPYTER_PATH": str(run_folder / "jupyter_data"),
        "JUPYTER_NO_CONFIG": "1",
        "MPLBACKEND": "Agg",
    })
    if python is not None:
        python_path = Path(python).absolute()
        env["VIRTUAL_ENV"] = str(python_path.parent.parent)
        env["PATH"] = str(python_path.parent) + os.pathsep + env.get("PATH", "")
    for name in ("IPYTHONDIR", "MPLCONFIGDIR", "JUPYTER_DATA_DIR", "JUPYTER_CONFIG_DIR", "JUPYTER_RUNTIME_DIR"):
        Path(env[name]).mkdir(parents=True, exist_ok=True)
    return env


def _memory():
    try:
        return {"physical_memory_bytes": os.sysconf("SC_PAGE_SIZE") * os.sysconf("SC_PHYS_PAGES"),
                "available_memory_bytes": os.sysconf("SC_PAGE_SIZE") * os.sysconf("SC_AVPHYS_PAGES")}
    except (AttributeError, ValueError, OSError):
        return {"physical_memory_bytes": None, "available_memory_bytes": None}


_INSPECT = """import importlib.metadata as m,json,os,platform,site,sys
print(json.dumps({'sys_executable':sys.executable,'sys_prefix':sys.prefix,'sys_base_prefix':sys.base_prefix,'python_version':platform.python_version(),'sys_path':sys.path,'user_site_enabled':site.ENABLE_USER_SITE,'pid':os.getpid(),'packages':{d.metadata['Name']:d.version for d in m.distributions()}},sort_keys=True))
"""


def prepare_environment(run_folder, requirements, config, emit=None):
    """Install pins in a NEW venv and preserve both successful and failed setup.

    ``config`` supports ``wheelhouse`` (offline ``--no-index`` installation),
    ``pip_index_url``, ``pip_extra_index_url``/``pip_extra_index_urls``, and finite
    ``pip_install_timeout_seconds``/``pip_network_timeout_seconds``/``pip_retries``.
    A failed install returns ``status='failed'`` without trying a host interpreter.
    An existing environment directory raises FileExistsError and is untouched.
    """
    config = dict(config or {})
    run_folder = Path(run_folder).resolve()
    run_folder.mkdir(parents=True, exist_ok=True)
    folder = run_folder / "environment"
    folder.mkdir(exist_ok=False)
    requirements_path = folder / "requirements.txt"
    python = folder / "venv" / ("Scripts/python.exe" if os.name == "nt" else "bin/python")
    python = python.absolute()  # Do not resolve the venv symlink to its base Python.
    record_path = run_folder / "environment.json"
    record = {
        "schema_version": "step36-analysis-environment-1", "status": "running", "started_at": _now(),
        "mode": "fresh_install", "fresh_dependency_install_tested": False,
        "system_site_packages": False, "python": str(python), "launcher_python": sys.executable,
        "platform": platform.platform(), "os": platform.system(), "machine": platform.machine(),
        "cpu": platform.processor() or None, "cpu_count": os.cpu_count(), **_memory(),
        "accelerator_check": "not_required_for_saved_analysis; no model runtime imported",
        "requirements_file": str(requirements_path), "environment_folder": str(folder),
        "venv_creation": {"method": "venv.EnvBuilder(with_pip=True, system_site_packages=False, clear=False)",
                          "path": str(folder / "venv")},
        "install_stdout": str(folder / "install_stdout.log"), "install_stderr": str(folder / "install_stderr.log"),
        "pip_report": str(folder / "pip_report.json"), "pip_freeze": str(folder / "pip_freeze.txt"),
    }
    result = {"status": "failed", "python": str(python), "environment": record,
              "environment_file": str(record_path), "requirements_file": str(requirements_path)}
    started = time.monotonic()
    (folder / "install_stdout.log").write_text("", encoding="utf-8")
    (folder / "install_stderr.log").write_text("", encoding="utf-8")
    raw_report = folder / "pip_report.raw.json"
    _write_json(record_path, record)
    try:
        if config.get("environment_mode", "fresh_install") != "fresh_install":
            raise ValueError("This runner requires an independent fresh_install environment.")
        exact = _pins(requirements)
        requirements_path.write_text("\n".join(exact) + "\n", encoding="utf-8")
        record["requirements"] = exact
        install_timeout = float(config.get("pip_install_timeout_seconds", 600))
        network_timeout = float(config.get("pip_network_timeout_seconds", 30))
        retries = int(config.get("pip_retries", 1))
        if not 0 < install_timeout <= 3600 or not 0 < network_timeout <= 300 or not 0 <= retries <= 5:
            raise ValueError("Pip timeouts/retries must be finite and within the documented limits.")
        if emit:
            emit("Our team is creating the separate analysis environment.")
        # venv refuses no existing path on its own, so enforce that explicitly.
        if (folder / "venv").exists():
            raise FileExistsError("The analysis venv already exists; choose a new run directory.")
        venv.EnvBuilder(with_pip=True, system_site_packages=False, clear=False).create(folder / "venv")
        command = [str(python), "-m", "pip", "install", "--disable-pip-version-check", "--no-input",
                   "--timeout", str(network_timeout), "--retries", str(retries), "--report", str(raw_report),
                   "-r", str(requirements_path)]
        wheelhouse = config.get("wheelhouse")
        if wheelhouse:
            wheelhouse = Path(wheelhouse).expanduser().resolve(strict=True)
            if not wheelhouse.is_dir():
                raise ValueError("wheelhouse must name an existing local directory.")
            command.extend(["--no-index", "--find-links", str(wheelhouse)])
            record["package_sources"] = {"mode": "local_wheelhouse", "wheelhouse": str(wheelhouse)}
        else:
            sources = {"mode": "configured_pip_index", "index_url": config.get("pip_index_url", "pip configured/default index")}
            if config.get("pip_index_url"):
                command.extend(["--index-url", str(config["pip_index_url"])])
            extra = config.get("pip_extra_index_urls", config.get("pip_extra_index_url", []))
            extra = [extra] if isinstance(extra, str) else list(extra)
            for url in extra:
                command.extend(["--extra-index-url", str(url)])
            sources["extra_index_urls"] = extra
            record["package_sources"] = redact(sources)
        record["install_command"] = redact(command)
        record["install_timeout_seconds"] = install_timeout
        _write_json(record_path, record)
        env = isolated_environment(run_folder, python)
        try:
            completed = subprocess.run(command, env=env, capture_output=True, text=True, timeout=install_timeout, check=False)
            stdout, stderr = completed.stdout, completed.stderr
            record["install_returncode"] = completed.returncode
        except subprocess.TimeoutExpired as exc:
            stdout, stderr = exc.stdout or "", exc.stderr or ""
            if isinstance(stdout, bytes):
                stdout = stdout.decode("utf-8", "replace")
            if isinstance(stderr, bytes):
                stderr = stderr.decode("utf-8", "replace")
            record["install_returncode"] = None
            record["install_timed_out"] = True
        (folder / "install_stdout.log").write_text(redact(stdout), encoding="utf-8")
        (folder / "install_stderr.log").write_text(redact(stderr), encoding="utf-8")
        if record.get("install_returncode") != 0:
            raise RuntimeError("Fresh-environment dependency installation failed; inspect the preserved install logs.")
        inspection = subprocess.run([str(python), "-I", "-c", _INSPECT], env=env, capture_output=True,
                                    text=True, timeout=60, check=False)
        (folder / "inspection_stderr.log").write_text(redact(inspection.stderr), encoding="utf-8")
        if inspection.returncode:
            raise RuntimeError("The new environment could not report its interpreter and installed packages.")
        observed = json.loads(inspection.stdout)
        record["interpreter"] = observed
        if observed["sys_prefix"] == observed["sys_base_prefix"] or observed["user_site_enabled"]:
            raise RuntimeError("The installed interpreter is not an isolated virtual environment.")
        observed_packages = {key.lower().replace("_", "-"): value for key, value in observed["packages"].items()}
        for requirement in exact:
            name, version = requirement.split("==")
            if observed_packages.get(name) != version:
                raise RuntimeError("Installed package does not match its analysis pin: " + name)
        frozen = subprocess.run([str(python), "-m", "pip", "freeze", "--all", "--disable-pip-version-check"],
                                env=env, capture_output=True, text=True, timeout=60, check=False)
        (folder / "pip_freeze.txt").write_text(redact(frozen.stdout), encoding="utf-8")
        (folder / "pip_freeze_stderr.log").write_text(redact(frozen.stderr), encoding="utf-8")
        if frozen.returncode:
            raise RuntimeError("Recording pip freeze failed in the new environment.")
        kernel_name = "step36-analysis"
        kernel_folder = run_folder / "jupyter_data" / "kernels" / kernel_name
        kernel_folder.mkdir(parents=True, exist_ok=False)
        spec = {"argv": [str(python), "-m", "ipykernel_launcher", "-f", "{connection_file}"],
                "display_name": "Step 36 isolated analysis", "language": "python"}
        _write_json(kernel_folder / "kernel.json", spec)
        record.update({"status": "passed", "fresh_dependency_install_tested": True,
                       "kernel_name": kernel_name, "kernel_spec": spec,
                       "kernel_spec_path": str(kernel_folder / "kernel.json"),
                       "jupyter_data_dir": str(run_folder / "jupyter_data")})
        result.update({"status": "passed", "kernel_name": kernel_name,
                       "kernel_spec_path": str(kernel_folder / "kernel.json"),
                       "jupyter_data_dir": str(run_folder / "jupyter_data")})
        if emit:
            emit("Our team installed and recorded the pinned analysis dependencies.")
    except Exception as exc:
        record.update({"status": "failed", "error_type": type(exc).__name__, "error": redact(str(exc))})
        if emit:
            emit("Our team retained the failed environment setup and its logs.")
    finally:
        if raw_report.exists():
            try:
                _write_json(folder / "pip_report.json", redact(json.loads(raw_report.read_text(encoding="utf-8"))))
            except (ValueError, OSError) as exc:
                _write_json(folder / "pip_report.json", {"status": "unreadable", "error": redact(str(exc))})
            raw_report.unlink()
        elif not (folder / "pip_report.json").exists():
            _write_json(folder / "pip_report.json", {"status": "not_produced", "install_returncode": record.get("install_returncode")})
        if python.exists() and not (folder / "pip_freeze.txt").exists():
            # Failure evidence should show any packages actually left installed,
            # including pip/setuptools in an otherwise empty new environment.
            try:
                env = isolated_environment(run_folder, python)
                frozen = subprocess.run([str(python), "-m", "pip", "freeze", "--all", "--disable-pip-version-check"],
                                        env=env, capture_output=True, text=True, timeout=30, check=False)
                (folder / "pip_freeze.txt").write_text(redact(frozen.stdout), encoding="utf-8")
                (folder / "pip_freeze_stderr.log").write_text(redact(frozen.stderr), encoding="utf-8")
                record["freeze_returncode"] = frozen.returncode
                if "interpreter" not in record:
                    inspected = subprocess.run([str(python), "-I", "-c", _INSPECT], env=env, capture_output=True,
                                               text=True, timeout=30, check=False)
                    if inspected.returncode == 0:
                        record["interpreter"] = json.loads(inspected.stdout)
            except (OSError, ValueError, subprocess.TimeoutExpired) as exc:
                record["failed_setup_inspection_error"] = redact(str(exc))
        if not (folder / "pip_freeze.txt").exists():
            (folder / "pip_freeze.txt").write_text("", encoding="utf-8")
            record["freeze_status"] = "not_produced"
        record.update({"finished_at": _now(), "elapsed_seconds": round(time.monotonic() - started, 6)})
        _write_json(record_path, redact(record))
    return result
